// ---------------------------------------------------------------------------
// Procedural audio - no external assets required.
// ---------------------------------------------------------------------------

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.sfx = null
    this.music = null
    this.noiseBuffer = null
    this.enabled = true
    this.musicEnabled = true
    this.musicTimer = null
    this.step = 0
    this.nextNote = 0
    this.bpm = 96
    this.formLevel = 0
    this.startedMusic = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.65
    this.master.connect(this.ctx.destination)

    this.sfx = this.ctx.createGain()
    this.sfx.gain.value = 0.8
    this.sfx.connect(this.master)

    this.music = this.ctx.createGain()
    this.music.gain.value = 0.14
    this.music.connect(this.master)

    const len = this.ctx.sampleRate * 2
    this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = this.noiseBuffer.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    this.startMusic()
  }

  setEnabled(value) {
    this.enabled = value
    if (this.master) this.master.gain.setTargetAtTime(value ? 0.65 : 0, this.ctx.currentTime, 0.05)
  }

  setMusicEnabled(value) {
    this.musicEnabled = value
    if (this.music) this.music.gain.setTargetAtTime(value ? 0.14 : 0, this.ctx.currentTime, 0.05)
  }

  setForm(level) {
    this.formLevel = level
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0
  }

  // -------------------------------------------------------------- primitives
  tone({ freq = 440, freqEnd = null, type = 'sine', dur = 0.2, vol = 0.2, when = 0, attack = 0.005, release = 0.1, detune = 0, filter = 0, dest = null }) {
    if (!this.ctx || !this.enabled) return
    const t = this.now() + when
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(Math.max(20, freq), t)
    if (freqEnd) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t + dur)
    if (detune) osc.detune.value = detune
    gain.gain.setValueAtTime(0.0001, t)
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + attack)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    let node = osc
    if (filter) {
      const bq = this.ctx.createBiquadFilter()
      bq.type = 'lowpass'
      bq.frequency.value = filter
      node.connect(bq)
      node = bq
    }
    node.connect(gain)
    gain.connect(dest || this.sfx)
    osc.start(t)
    osc.stop(t + dur + 0.05)
  }

  noise({ dur = 0.15, vol = 0.2, when = 0, filter = 1800, filterEnd = null, type = 'lowpass', q = 1, dest = null }) {
    if (!this.ctx || !this.enabled || !this.noiseBuffer) return
    const t = this.now() + when
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const bq = this.ctx.createBiquadFilter()
    bq.type = type
    bq.Q.value = q
    bq.frequency.setValueAtTime(filter, t)
    if (filterEnd) bq.frequency.exponentialRampToValueAtTime(Math.max(40, filterEnd), t + dur)
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(0.0001, t)
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(bq)
    bq.connect(gain)
    gain.connect(dest || this.sfx)
    src.start(t)
    src.stop(t + dur + 0.05)
  }

  // -------------------------------------------------------------- SFX
  ui() {
    this.tone({ freq: 620, freqEnd: 880, type: 'triangle', dur: 0.08, vol: 0.12 })
  }

  punch() {
    this.noise({ dur: 0.09, vol: 0.28, filter: 2200, filterEnd: 300 })
    this.tone({ freq: 150, freqEnd: 52, type: 'sine', dur: 0.14, vol: 0.3 })
  }

  heavy() {
    this.noise({ dur: 0.18, vol: 0.36, filter: 1600, filterEnd: 220 })
    this.tone({ freq: 110, freqEnd: 38, type: 'sine', dur: 0.26, vol: 0.42 })
    this.tone({ freq: 220, freqEnd: 90, type: 'triangle', dur: 0.12, vol: 0.12 })
  }

  hit() {
    this.noise({ dur: 0.08, vol: 0.2, filter: 3200, filterEnd: 600 })
    this.tone({ freq: 260, freqEnd: 80, type: 'sawtooth', dur: 0.08, vol: 0.08 })
  }

  block() {
    this.tone({ freq: 1250, freqEnd: 620, type: 'square', dur: 0.1, vol: 0.09, filter: 3000 })
    this.noise({ dur: 0.06, vol: 0.1, filter: 5200, type: 'highpass' })
  }

  whoosh() {
    this.noise({ dur: 0.17, vol: 0.16, filter: 380, filterEnd: 2600, type: 'bandpass', q: 1.8 })
  }

  dash() {
    this.noise({ dur: 0.22, vol: 0.22, filter: 600, filterEnd: 4200, type: 'bandpass', q: 1.2 })
    this.tone({ freq: 300, freqEnd: 900, type: 'sine', dur: 0.16, vol: 0.06 })
  }

  jump() {
    this.tone({ freq: 240, freqEnd: 480, type: 'triangle', dur: 0.16, vol: 0.08 })
  }

  ki() {
    this.tone({ freq: 1100, freqEnd: 260, type: 'sine', dur: 0.2, vol: 0.14 })
    this.tone({ freq: 2200, freqEnd: 900, type: 'triangle', dur: 0.12, vol: 0.05 })
  }

  beamCharge() {
    this.tone({ freq: 160, freqEnd: 640, type: 'sawtooth', dur: 0.65, vol: 0.1, filter: 1200 })
    this.noise({ dur: 0.6, vol: 0.08, filter: 300, filterEnd: 2600, type: 'bandpass', q: 2 })
  }

  beam() {
    this.tone({ freq: 720, freqEnd: 140, type: 'sawtooth', dur: 0.75, vol: 0.18, filter: 1800 })
    this.tone({ freq: 1400, freqEnd: 220, type: 'square', dur: 0.6, vol: 0.06, filter: 2600 })
    this.noise({ dur: 0.7, vol: 0.18, filter: 1800, filterEnd: 260, type: 'lowpass' })
  }

  explosion() {
    this.noise({ dur: 0.6, vol: 0.5, filter: 1200, filterEnd: 90 })
    this.tone({ freq: 90, freqEnd: 28, type: 'sine', dur: 0.7, vol: 0.5 })
    this.tone({ freq: 200, freqEnd: 50, type: 'sawtooth', dur: 0.3, vol: 0.12, filter: 600 })
  }

  flash() {
    this.tone({ freq: 1800, freqEnd: 3600, type: 'sine', dur: 0.4, vol: 0.18 })
    this.noise({ dur: 0.35, vol: 0.2, filter: 6000, type: 'highpass' })
  }

  teleport() {
    this.tone({ freq: 1300, freqEnd: 180, type: 'sine', dur: 0.24, vol: 0.16 })
    this.tone({ freq: 600, freqEnd: 1600, type: 'triangle', dur: 0.18, vol: 0.08, when: 0.1 })
  }

  transform(level = 1) {
    if (!this.ctx || !this.enabled) return
    const base = 130 + level * 12
    for (let i = 0; i < 7; i++) {
      this.tone({ freq: base * Math.pow(1.26, i), freqEnd: base * Math.pow(1.26, i) * 1.5, type: 'sawtooth', dur: 1.2 - i * 0.08, vol: 0.055, when: i * 0.055, filter: 2200 })
    }
    this.tone({ freq: 65, freqEnd: 42, type: 'sine', dur: 1.4, vol: 0.45 })
    this.noise({ dur: 1.3, vol: 0.32, filter: 500, filterEnd: 5000, type: 'bandpass', q: 0.7 })
    this.noise({ dur: 0.8, vol: 0.18, filter: 7000, type: 'highpass', when: 0.1 })
  }

  spirit() {
    if (!this.ctx || !this.enabled) return
    for (let i = 0; i < 10; i++) {
      this.tone({ freq: 400 + i * 110, freqEnd: 800 + i * 130, type: 'sine', dur: 1.6, vol: 0.04, when: i * 0.06 })
    }
  }

  ko() {
    this.tone({ freq: 220, freqEnd: 40, type: 'sawtooth', dur: 1.4, vol: 0.24, filter: 900 })
    this.tone({ freq: 110, freqEnd: 28, type: 'sine', dur: 1.6, vol: 0.3 })
    this.noise({ dur: 1.0, vol: 0.2, filter: 900, filterEnd: 120 })
  }

  victory() {
    if (!this.ctx || !this.enabled) return
    const notes = [261.6, 329.6, 392, 523.25, 659.25, 783.99]
    notes.forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 1.4, vol: 0.11, when: i * 0.12, filter: 4000 }))
    this.tone({ freq: 130.8, type: 'sine', dur: 2.2, vol: 0.18, when: 0.1 })
  }

  defeat() {
    const notes = [220, 196, 174.6, 146.8]
    notes.forEach((f, i) => this.tone({ freq: f, type: 'sawtooth', dur: 1.2, vol: 0.09, when: i * 0.24, filter: 700 }))
  }

  // -------------------------------------------------------------- music
  startMusic() {
    if (!this.ctx || this.startedMusic) return
    this.startedMusic = true
    this.nextNote = this.ctx.currentTime + 0.15
    this.musicTimer = setInterval(() => this.scheduleMusic(), 45)
  }

  scheduleMusic() {
    if (!this.ctx) return
    const ahead = 0.3
    while (this.nextNote < this.ctx.currentTime + ahead) {
      if (this.musicEnabled) this.playStep(this.step, this.nextNote - this.now())
      this.nextNote += 60 / this.bpm / 4
      this.step = (this.step + 1) % 32
    }
  }

  playStep(step, when) {
    const bar = Math.floor(step / 8) % 4
    const roots = [55, 43.65, 65.41, 49] // A F C G
    const chords = [
      [220, 261.63, 329.63],
      [174.61, 220, 261.63],
      [261.63, 329.63, 392],
      [196, 246.94, 293.66]
    ]
    const root = roots[bar]
    // Kick
    if (step % 4 === 0) {
      this.tone({ freq: 120, freqEnd: 42, type: 'sine', dur: 0.22, vol: 0.3, when, dest: this.music })
    }
    // Snare
    if (step % 8 === 4) {
      this.noise({ dur: 0.1, vol: 0.075, filter: 2400, filterEnd: 800, when, dest: this.music })
    }
    // Hats
    if (step % 2 === 1) {
      this.noise({ dur: 0.035, vol: 0.022, filter: 8000, type: 'highpass', when, dest: this.music })
    }
    // Bass pulse
    if (step % 2 === 0) {
      this.tone({ freq: root, type: 'sawtooth', dur: 0.14, vol: 0.11, when, filter: 240, dest: this.music })
    }
    // Arpeggio
    if (step % 2 === 0) {
      const chord = chords[bar]
      const note = chord[(step / 2) % 3]
      this.tone({ freq: note * 2, type: 'triangle', dur: 0.18, vol: 0.035, when, filter: 3200, dest: this.music })
    }
    // Pad at bar start
    if (step % 8 === 0) {
      const chord = chords[bar]
      chord.forEach((f, i) => {
        this.tone({ freq: f, type: 'sawtooth', dur: 1.25, vol: 0.018, when, filter: 900, detune: i * 5, dest: this.music })
      })
    }
    // Tension lines in higher forms
    if (this.formLevel >= 5 && step % 4 === 2) {
      this.tone({ freq: 880 + this.formLevel * 40, type: 'sine', dur: 0.1, vol: 0.012, when, dest: this.music })
    }
  }
}

:root {
  --orange: #ff8a1f;
  --gold: #ffd23f;
  --gold-soft: #ffe9a3;
  --red: #ff3b54;
  --cyan: #4bdcff;
  --blue: #2e7bff;
  --ink: #060813;
  --panel: rgba(10, 13, 28, 0.82);
  --line: rgba(255, 210, 63, 0.36);
  --text: #f6f4ee;
  --muted: #9ea8c6;
  --display: 'Impact', 'Haettenschweiler', 'Arial Narrow Bold', 'Trebuchet MS', sans-serif;
  --body: 'Trebuchet MS', 'Segoe UI', system-ui, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--text);
  font-family: var(--body);
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
}

body { touch-action: none; }
button { font-family: inherit; color: inherit; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border: 1px solid rgba(255, 255, 255, 0.26);
  border-bottom-color: rgba(255, 255, 255, 0.45);
  border-radius: 4px;
  background: linear-gradient(180deg, rgba(255,255,255,0.13), rgba(255,255,255,0.02));
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  font-family: var(--body);
  box-shadow: 0 2px 0 rgba(0,0,0,0.25);
  white-space: nowrap;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #05060e;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 42%, rgba(2, 3, 10, 0.5) 100%),
    linear-gradient(180deg, rgba(2,3,10,0.45), transparent 16%, transparent 80%, rgba(2,3,10,0.55));
  z-index: 2;
}

#flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: #fff;
  z-index: 20;
  mix-blend-mode: screen;
}

.hidden { display: none !important; }

/* ================================ HUD ================================ */
#hud {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.45s ease;
}
#hud.on { opacity: 1; }

.enemy-hud {
  position: absolute;
  top: calc(var(--safe-top) + 20px);
  left: 50%;
  transform: translateX(-50%) skewX(-3deg);
  width: min(780px, 82vw);
  filter: drop-shadow(0 6px 18px rgba(0, 0, 0, 0.6));
}
.enemy-meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin: 0 4px 5px;
  color: #bfc8e6;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.enemy-meta span:last-child { color: #ff9b7a; }
.enemy-name-row {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin: 0 4px 7px;
  text-transform: uppercase;
}
.enemy-name-row strong {
  font-family: var(--display);
  font-size: clamp(22px, 2.3vw, 34px);
  letter-spacing: 0.04em;
  line-height: 1;
  color: #fff;
  text-shadow: 0 0 22px rgba(255, 72, 100, 0.65), 2px 3px 0 rgba(0,0,0,0.6);
}
.enemy-name-row span {
  color: #ff879b;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
}
.bar {
  position: relative;
  width: 100%;
  background: rgba(4, 6, 16, 0.82);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.7);
}
.enemy-bar { height: 18px; clip-path: polygon(0 0, 100% 0, calc(100% - 11px) 100%, 0 100%); }
.bar-fill, .bar-ghost {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 100%;
  transform-origin: left center;
}
.bar-ghost {
  background: linear-gradient(90deg, #ffcf70, #ff8b4a);
  opacity: 0.55;
  transition: width 0.55s cubic-bezier(.2,.7,.3,1);
}
.enemy-bar .bar-fill {
  background: linear-gradient(90deg, #ff2f61, #ff6b4a 45%, #ffb03a);
  box-shadow: 0 0 18px rgba(255, 60, 90, 0.65);
  transition: width 0.16s linear;
}
.bar-shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255,255,255,0.28), transparent 46%, rgba(0,0,0,0.18));
  pointer-events: none;
}

.fight-info {
  position: absolute;
  top: calc(var(--safe-top) + 18px);
  right: calc(var(--safe-right) + 22px);
  display: flex;
  gap: 9px;
  align-items: center;
  color: #c7cdea;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.78;
}
.fight-info .dot { color: var(--orange); font-size: 7px; }

.player-hud {
  position: absolute;
  left: calc(var(--safe-left) + 24px);
  bottom: calc(var(--safe-bottom) + 22px);
  width: min(440px, 37vw);
  display: flex;
  gap: 12px;
  align-items: flex-end;
  filter: drop-shadow(0 8px 20px rgba(0, 0, 0, 0.65));
}
.form-badge {
  --form-color: #ffcf4a;
  flex: 0 0 auto;
  width: 68px;
  height: 74px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  background: linear-gradient(160deg, rgba(20, 24, 46, 0.95), rgba(8, 10, 24, 0.92));
  border: 1px solid var(--form-color);
  clip-path: polygon(14% 0, 100% 0, 100% 82%, 86% 100%, 0 100%, 0 18%);
  box-shadow: inset 0 0 24px color-mix(in srgb, var(--form-color) 18%, transparent), 0 0 24px color-mix(in srgb, var(--form-color) 28%, transparent);
  position: relative;
}
.form-badge::after {
  content: '';
  position: absolute;
  inset: 6px;
  border: 1px solid color-mix(in srgb, var(--form-color) 35%, transparent);
  clip-path: inherit;
  pointer-events: none;
}
.form-badge span {
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.04em;
  color: var(--form-color);
  text-shadow: 0 0 12px var(--form-color);
  max-width: 82%;
  text-align: center;
  line-height: 1;
}
.form-badge small { font-size: 7px; letter-spacing: 0.24em; color: #8792b4; }
.player-main { flex: 1 1 auto; min-width: 0; }
.player-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  margin: 0 2px 6px;
  text-transform: uppercase;
  white-space: nowrap;
}
.player-top strong {
  font-family: var(--display);
  letter-spacing: 0.05em;
  font-size: 23px;
  line-height: 1;
  text-shadow: 2px 2px 0 #000;
}
.player-top span {
  color: var(--gold);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  overflow: hidden;
  text-overflow: ellipsis;
}
.player-main .bar { height: 11px; margin-bottom: 4px; }
.player-main .bar.ki { height: 7px; }
.player-main .bar.power { height: 9px; }
.player-main .bar.spirit { height: 6px; }
.bar.hp .bar-fill { background: linear-gradient(90deg, #25e37d, #b4ff52 60%, #ffd23f); transition: width 0.16s linear; }
.bar.hp.low .bar-fill { background: linear-gradient(90deg, #ff2954, #ff6a3d 60%, #ffb03a); animation: lowPulse 0.8s infinite; }
.bar.ki .bar-fill { background: linear-gradient(90deg, #1e8dff, #6ce8ff); box-shadow: 0 0 12px rgba(65, 195, 255, 0.55); transition: width 0.12s linear; }
.bar.power .bar-fill { background: linear-gradient(90deg, #ff4d6d, #ff9b2f 55%, #ffe14d); box-shadow: 0 0 12px rgba(255, 150, 50, 0.5); transition: width 0.09s linear; }
.bar.spirit .bar-fill { background: linear-gradient(90deg, #4a7bff, #b6f4ff); transition: width 0.12s linear; }
.bar.power.ready { animation: readyGlow 0.62s infinite alternate; }
.bar.power.ready .bar-fill { background: linear-gradient(90deg, #ffd23f, #fff7c2, #ffd23f); background-size: 200% 100%; animation: readySlide 0.7s linear infinite; }
.bar-label {
  position: absolute;
  right: 5px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: rgba(200, 212, 240, 0.8);
  text-shadow: 1px 1px 0 #000;
  pointer-events: none;
}
.bar-label b { color: #fff; }
.player-foot {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin: 5px 2px 0;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #8f9bbc;
  text-transform: uppercase;
  white-space: nowrap;
}
.player-foot b { color: #ffd98a; font-size: 10px; }
.player-foot kbd { height: 15px; min-width: 15px; font-size: 8px; }
#transform-hint { color: #ffc94a; animation: softBlink 1.4s infinite; }

@keyframes lowPulse { 50% { filter: brightness(1.6); } }
@keyframes readyGlow { from { box-shadow: inset 0 2px 6px rgba(0,0,0,.7), 0 0 6px rgba(255,210,63,.3); } to { box-shadow: inset 0 2px 6px rgba(0,0,0,.7), 0 0 20px rgba(255,210,63,.95); } }
@keyframes readySlide { to { background-position: 200% 0; } }
@keyframes softBlink { 50% { opacity: 0.45; } }

#combo {
  position: absolute;
  right: calc(var(--safe-right) + 34px);
  top: 42%;
  display: flex;
  align-items: center;
  gap: 8px;
  opacity: 0;
  transform: scale(0.86) skewX(-6deg);
  transition: opacity 0.16s, transform 0.16s;
  filter: drop-shadow(0 6px 14px rgba(0, 0, 0, 0.6));
}
#combo.on { opacity: 1; transform: scale(1) skewX(-6deg); }
#combo-num {
  font-family: var(--display);
  font-size: clamp(48px, 6vw, 84px);
  line-height: 0.8;
  color: var(--gold);
  -webkit-text-stroke: 1px rgba(255,255,255,0.5);
  text-shadow: 0 0 26px rgba(255, 180, 40, 0.75), 4px 4px 0 #6b2a00;
}
#combo em {
  font-style: normal;
  font-size: 11px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #fff;
  text-shadow: 2px 2px 0 #000;
}

#skillbar {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 20px);
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  pointer-events: auto;
}
.skill {
  --cd: 0%;
  position: relative;
  width: 64px;
  height: 64px;
  padding: 4px 3px 3px;
  border: 1px solid rgba(255, 210, 63, 0.5);
  background: linear-gradient(180deg, rgba(22, 26, 52, 0.95), rgba(6, 8, 20, 0.92));
  clip-path: polygon(10% 0, 100% 0, 100% 84%, 88% 100%, 0 100%, 0 16%);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  overflow: hidden;
  box-shadow: inset 0 0 18px rgba(255, 180, 60, 0.06), 0 4px 12px rgba(0,0,0,0.35);
  transition: transform 0.12s, border-color 0.12s, filter 0.12s;
}
.skill:hover { transform: translateY(-2px); border-color: var(--gold); filter: brightness(1.2); }
.skill:active { transform: translateY(1px) scale(0.97); }
.skill-glyph {
  font-size: 20px;
  line-height: 1;
  color: var(--gold);
  text-shadow: 0 0 12px rgba(255, 200, 50, 0.75);
  font-family: serif;
}
.skill-name { font-size: 7px; font-weight: 800; letter-spacing: 0.1em; color: #dbe2f5; }
.skill-key {
  position: absolute;
  top: 2px;
  left: 4px;
  font-size: 8px;
  font-weight: 800;
  color: #fff;
  opacity: 0.65;
}
.skill-cost {
  position: absolute;
  right: 4px;
  bottom: 2px;
  font-size: 7px;
  font-weight: 800;
  color: #5fd4ff;
  opacity: 0.85;
}
.skill-cd {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--cd);
  background: rgba(1, 2, 8, 0.78);
  pointer-events: none;
  transition: height 0.1s linear;
}
.skill.locked { filter: grayscale(1) brightness(0.55); }
.skill.locked .skill-glyph { color: #8b93a8; text-shadow: none; }
.skill.ready { border-color: #ffe98a; box-shadow: inset 0 0 24px rgba(255, 211, 63, 0.15), 0 0 16px rgba(255, 211, 63, 0.35); }
.skill.pulse { animation: skillPulse 0.7s infinite alternate; }
@keyframes skillPulse { from { filter: brightness(0.9); } to { filter: brightness(1.4); } }

#combo-timer-wrap {
  position: absolute;
  right: calc(var(--safe-right) + 34px);
  top: calc(42% + 64px);
  width: 110px;
  height: 3px;
  background: rgba(255,255,255,0.12);
  opacity: 0;
  transform: skewX(-6deg);
  transition: opacity 0.2s;
}
#combo-timer-wrap.on { opacity: 1; }
#combo-timer { height: 100%; width: 100%; background: linear-gradient(90deg, #ff8a1f, #ffe14d); }

#hint-area {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 94px);
  transform: translateX(-50%);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: rgba(188, 201, 232, 0.7);
  text-transform: uppercase;
  white-space: nowrap;
  text-shadow: 1px 1px 2px #000;
  transition: opacity 0.4s;
}
#hint-area kbd { height: 16px; min-width: 16px; font-size: 8px; margin: 0 1px; }
.touch-hint { display: none; }

/* ============================== TOUCH =============================== */
#touch-controls { display: none; }
body.touch #touch-controls {
  display: block;
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
}
body.touch .desktop-hint { display: none; }
body.touch .touch-hint { display: inline; }
body.touch #hint-area {
  bottom: auto;
  top: calc(var(--safe-top) + 78px);
  font-size: 8px;
  color: rgba(190, 205, 235, 0.5);
}

#stick-zone {
  position: absolute;
  left: calc(var(--safe-left) + 20px);
  bottom: calc(var(--safe-bottom) + 18px);
  width: 136px;
  height: 162px;
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
#stick-ring {
  width: 118px;
  height: 118px;
  border-radius: 50%;
  border: 1px solid rgba(120, 180, 255, 0.28);
  background: radial-gradient(circle at 50% 45%, rgba(80, 130, 255, 0.12), rgba(5, 8, 20, 0.5) 70%);
  box-shadow: inset 0 0 24px rgba(40, 100, 255, 0.12), 0 0 0 8px rgba(5, 8, 20, 0.18);
  position: relative;
  touch-action: none;
}
#stick-ring::before, #stick-ring::after {
  content: '';
  position: absolute;
  background: rgba(140, 190, 255, 0.12);
}
#stick-ring::before { left: 50%; top: 12px; bottom: 12px; width: 1px; }
#stick-ring::after { top: 50%; left: 12px; right: 12px; height: 1px; }
#stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 38% 32%, #d6e9ff, #4f84d8 38%, #142852 72%);
  border: 1px solid rgba(180, 220, 255, 0.6);
  box-shadow: 0 0 20px rgba(70, 150, 255, 0.55), inset 0 2px 6px rgba(255,255,255,0.35);
}
#stick-zone small {
  font-size: 7px;
  letter-spacing: 0.12em;
  color: rgba(180, 200, 235, 0.55);
  font-weight: 700;
  white-space: nowrap;
}

#action-pad {
  position: absolute;
  right: calc(var(--safe-right) + 14px);
  bottom: calc(var(--safe-bottom) + 16px);
  display: grid;
  grid-template-columns: repeat(3, 56px);
  grid-auto-rows: 56px;
  gap: 8px;
  pointer-events: auto;
  align-items: end;
}
.tact {
  border: 1px solid rgba(120, 175, 255, 0.42);
  background: radial-gradient(circle at 35% 26%, rgba(60, 96, 190, 0.65), rgba(8, 12, 30, 0.88) 68%);
  border-radius: 50%;
  font-family: var(--display);
  font-size: 12px;
  letter-spacing: 0.06em;
  color: #dfe9ff;
  text-shadow: 1px 1px 0 #000;
  box-shadow: 0 4px 14px rgba(0,0,0,0.5), inset 0 0 16px rgba(80, 140, 255, 0.16);
  touch-action: none;
  transition: transform 0.07s, filter 0.07s, background 0.07s;
}
.tact:active, .tact.down {
  transform: scale(0.92);
  filter: brightness(1.5);
  border-color: rgba(255, 220, 120, 0.85);
}
.tact.strike {
  background: radial-gradient(circle at 35% 26%, rgba(255, 165, 40, 0.95), rgba(120, 45, 5, 0.92) 66%);
  border-color: rgba(255, 210, 80, 0.84);
  color: #fff8d9;
  font-size: 14px;
  box-shadow: 0 0 22px rgba(255, 130, 30, 0.4), inset 0 0 18px rgba(255, 220, 120, 0.28);
}
.tact[data-act="power"].full {
  background: radial-gradient(circle at 35% 26%, rgba(255, 230, 100, 0.98), rgba(170, 90, 5, 0.92) 66%);
  border-color: #fff1a0;
  animation: powerPulse 0.8s infinite alternate;
}
@keyframes powerPulse { from { box-shadow: 0 0 12px rgba(255, 210, 63, 0.4); } to { box-shadow: 0 0 30px rgba(255, 230, 90, 0.95); } }

body.touch .player-hud {
  left: calc(var(--safe-left) + 12px);
  bottom: auto;
  top: calc(var(--safe-top) + 94px);
  width: min(54vw, 310px);
  gap: 8px;
}
body.touch .form-badge { width: 52px; height: 58px; }
body.touch .form-badge span { font-size: 13px; }
body.touch .player-top strong { font-size: 17px; }
body.touch .player-top span { font-size: 8px; }
body.touch .player-foot { display: none; }
body.touch .enemy-hud { top: calc(var(--safe-top) + 8px); width: 94vw; }
body.touch .enemy-name-row strong { font-size: 24px; }
body.touch .enemy-meta { font-size: 8px; }
body.touch .enemy-bar { height: 14px; }
body.touch .fight-info { display: none; }
body.touch #skillbar {
  left: auto;
  right: calc(var(--safe-right) + 12px);
  bottom: auto;
  top: calc(var(--safe-top) + 94px);
  transform: none;
  display: grid;
  grid-template-columns: repeat(2, 46px);
  gap: 5px;
}
body.touch .skill { width: 46px; height: 46px; padding: 2px; }
body.touch .skill-glyph { font-size: 16px; }
body.touch .skill-name { font-size: 6px; }
body.touch .skill-key { display: none; }
body.touch .skill-cost { font-size: 6px; }
body.touch #combo { right: calc(var(--safe-right) + 14px); top: 34%; }
body.touch #combo-num { font-size: 48px; }
body.touch #combo em { font-size: 8px; }
body.touch #combo-timer-wrap { right: calc(var(--safe-right) + 14px); top: calc(34% + 46px); width: 84px; }
body.touch #transform-hint { display: none; }

@media (max-width: 560px) {
  body.touch .player-hud { width: 57vw; }
  body.touch .enemy-name-row strong { font-size: 20px; }
  #stick-zone { width: 118px; height: 146px; left: 12px; }
  #stick-ring { width: 104px; height: 104px; }
  #stick-knob { width: 46px; height: 46px; }
  #action-pad { grid-template-columns: repeat(3, 49px); grid-auto-rows: 49px; gap: 6px; }
  .tact { font-size: 10px; }
  .tact.strike { font-size: 12px; }
}
@media (max-height: 460px) and (orientation: landscape) {
  body.touch .player-hud { top: calc(var(--safe-top) + 62px); width: min(44vw, 300px); }
  body.touch .enemy-hud { top: calc(var(--safe-top) + 4px); }
  body.touch .enemy-meta { display: none; }
  body.touch #skillbar { top: calc(var(--safe-top) + 72px); }
  #stick-zone { height: 118px; }
  #stick-ring { width: 96px; height: 96px; }
  #stick-knob { width: 42px; height: 42px; }
  #action-pad { grid-template-columns: repeat(3, 46px); grid-auto-rows: 46px; gap: 5px; }
}

/* ============================== SCREENS ============================== */
.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(var(--safe-top) + 24px) calc(var(--safe-right) + 24px) calc(var(--safe-bottom) + 24px) calc(var(--safe-left) + 24px);
}

.title-screen {
  background:
    linear-gradient(90deg, rgba(4, 5, 14, 0.94) 0%, rgba(4, 5, 14, 0.7) 38%, transparent 68%),
    linear-gradient(0deg, rgba(4,5,14,0.8), transparent 30%);
  justify-content: flex-start;
  padding-left: max(6vw, 32px);
}
.title-wrap { width: min(660px, 92vw); position: relative; z-index: 2; }
.kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  color: #c9d2ed;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.32em;
}
.kicker span { display: block; width: 34px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.kicker span:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.logo { display: flex; flex-direction: column; transform: skewX(-5deg); margin-left: -4px; }
.logo-top {
  font-family: var(--display);
  font-size: clamp(20px, 3.1vw, 42px);
  letter-spacing: 0.2em;
  color: #e9edf8;
  text-shadow: 3px 3px 0 #000;
  line-height: 1;
}
.logo-super {
  font-family: var(--display);
  font-size: clamp(24px, 3.6vw, 48px);
  letter-spacing: 0.36em;
  color: var(--orange);
  line-height: 1;
  margin: 2px 0 0 4px;
  text-shadow: 3px 3px 0 #5b1b00;
}
.logo-main {
  font-family: var(--display);
  font-size: clamp(58px, 9.6vw, 138px);
  line-height: 0.82;
  letter-spacing: 0.005em;
  background: linear-gradient(180deg, #fffdf0 0%, #ffe98a 22%, #ffb021 56%, #ff7a12 78%, #a33100 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(4px 6px 0 #2a0b00) drop-shadow(0 0 32px rgba(255, 140, 30, 0.35));
  -webkit-text-stroke: 1px rgba(255, 246, 200, 0.22);
  margin-top: 2px;
}
.tagline {
  margin: 22px 0 30px;
  font-size: clamp(10px, 1.1vw, 14px);
  font-weight: 800;
  letter-spacing: 0.34em;
  color: #9fb0d8;
  text-transform: uppercase;
}
.title-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.title-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 26px;
  color: #7f8bab;
  font-size: 9px;
  letter-spacing: 0.16em;
  font-weight: 700;
}
.title-meta .sep { color: var(--orange); font-size: 7px; }
#best-stage { color: #d4dcf0; }

.btn {
  position: relative;
  min-width: 150px;
  padding: 15px 30px;
  border: 1px solid transparent;
  clip-path: polygon(12px 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
  font-family: var(--display);
  font-size: 22px;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: transform 0.12s, filter 0.12s;
  text-transform: uppercase;
}
.btn:hover { transform: translateY(-2px); filter: brightness(1.12); }
.btn:active { transform: translateY(1px); }
.btn.primary {
  background: linear-gradient(135deg, #ffc93d, #ff7a12 62%, #c53c00);
  color: #200700;
  border-color: rgba(255, 244, 190, 0.8);
  box-shadow: 0 0 26px rgba(255, 130, 20, 0.35), inset 0 1px 0 rgba(255,255,255,0.45);
  text-shadow: 0 1px 0 rgba(255,255,255,0.3);
}
.btn.ghost {
  background: rgba(9, 12, 26, 0.65);
  border-color: rgba(150, 180, 255, 0.26);
  color: #d8e1f7;
  font-size: 18px;
  min-width: 140px;
}
.btn.ghost:hover { border-color: rgba(255, 210, 63, 0.55); }
.btn.danger { color: #ff9aa8; border-color: rgba(255, 80, 110, 0.3); }
.sound-btn {
  background: none;
  border: 1px solid rgba(150, 180, 255, 0.22);
  color: #9fb0d8;
  padding: 5px 9px;
  font-size: 8px;
  letter-spacing: 0.15em;
  font-weight: 800;
  cursor: pointer;
  margin-left: auto;
}
.sound-btn:hover { border-color: var(--gold); color: var(--gold); }

.title-corner {
  position: absolute;
  width: 34vw;
  height: 34vw;
  pointer-events: none;
  opacity: 0.25;
  background:
    repeating-linear-gradient(90deg, transparent 0 22px, rgba(255, 170, 40, 0.12) 22px 23px),
    repeating-linear-gradient(0deg, transparent 0 22px, rgba(255, 170, 40, 0.1) 22px 23px);
  mask-image: radial-gradient(circle, transparent 45%, #000 74%);
  -webkit-mask-image: radial-gradient(circle, transparent 45%, #000 74%);
}
.title-corner.left { left: -8vw; bottom: -10vw; }
.title-corner.right { right: -12vw; top: -12vw; transform: rotate(180deg); }

/* Panels */
.panel-screen { background: rgba(3, 4, 12, 0.72); backdrop-filter: blur(9px); }
.panel {
  position: relative;
  width: min(760px, 94vw);
  max-height: calc(100dvh - 48px);
  overflow: auto;
  background:
    linear-gradient(160deg, rgba(20, 25, 51, 0.97), rgba(7, 9, 21, 0.98)),
    radial-gradient(circle at 70% 0%, rgba(255, 140, 30, 0.14), transparent 50%);
  border: 1px solid rgba(255, 210, 63, 0.28);
  clip-path: polygon(26px 0, 100% 0, 100% calc(100% - 26px), calc(100% - 26px) 100%, 0 100%, 0 26px);
  padding: 38px 42px;
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7), inset 0 0 60px rgba(70, 100, 220, 0.07);
  scrollbar-width: thin;
}
.help-panel { width: min(980px, 96vw); }
.panel::before {
  content: '';
  position: absolute;
  inset: 10px;
  border: 1px solid rgba(255, 210, 63, 0.09);
  clip-path: inherit;
  pointer-events: none;
}
.panel h2 {
  margin: 4px 0 8px;
  font-family: var(--display);
  font-size: clamp(40px, 6vw, 68px);
  line-height: 0.92;
  letter-spacing: 0.02em;
  color: #fff;
  text-shadow: 3px 4px 0 #000, 0 0 30px rgba(255, 160, 40, 0.22);
}
.panel h2 em {
  font-style: normal;
  color: transparent;
  background: linear-gradient(180deg, #fff2b0, #ffb021 55%, #ff6a10);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(2px 3px 0 #3a1200);
}
.panel-kicker {
  color: var(--orange);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.34em;
  text-transform: uppercase;
}
.close-btn {
  position: absolute;
  top: 14px;
  right: 18px;
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.16);
  color: #cdd6ee;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
  z-index: 2;
}
.close-btn:hover { border-color: var(--gold); color: var(--gold); }

.help-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 22px 34px;
  margin: 26px 0 28px;
}
.help-col h3 {
  margin: 0 0 10px;
  font-size: 10px;
  letter-spacing: 0.24em;
  color: var(--gold);
  text-transform: uppercase;
}
.help-col.wide { grid-column: 1 / -1; }
.key-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 7px; }
.key-list li {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  color: #aeb9d6;
  font-size: 11px;
  line-height: 1.5;
}
.key-list li > span:first-child { color: #eef2ff; font-weight: 700; white-space: nowrap; }
.touch-list li > span:first-child { color: var(--gold); }
.help-note { color: #aeb9d6; font-size: 11px; line-height: 1.6; margin: 0; }
.help-note b { color: var(--gold); }
.tech-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.tech {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  padding: 10px;
  border: 1px solid rgba(120, 160, 255, 0.14);
  background: rgba(255,255,255,0.025);
}
.tech .tg {
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 210, 63, 0.4);
  color: var(--gold);
  font-size: 16px;
  background: rgba(255, 190, 50, 0.06);
}
.tech b { display: block; font-size: 9px; letter-spacing: 0.12em; color: #f0f3ff; }
.tech small { display: block; margin-top: 3px; font-size: 9px; line-height: 1.4; color: #8e9ab9; }

.panel-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 10px; }
.panel-actions.stacked { flex-direction: column; align-items: stretch; }
.panel-actions.stacked .btn { width: 100%; }
.panel-actions.stacked .btn + .btn { margin-top: 0; }
.pause-panel, .result-panel { width: min(560px, 92vw); text-align: left; }
.pause-form {
  margin: 16px 0 22px;
  font-family: var(--display);
  font-size: 26px;
  color: var(--gold);
  letter-spacing: 0.06em;
  text-shadow: 0 0 18px rgba(255, 210, 63, 0.4);
}
.tiny { margin: 18px 0 0; color: #737f9e; font-size: 9px; line-height: 1.5; letter-spacing: 0.04em; }

.result-sub {
  margin: 8px 0 18px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: #ff9aad;
  text-transform: uppercase;
}
.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.08);
  margin-bottom: 18px;
}
.stats > div {
  background: rgba(6, 8, 20, 0.96);
  padding: 11px 13px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.stats span { font-size: 8px; letter-spacing: 0.18em; color: #7e8aa8; font-weight: 800; }
.stats b { font-family: var(--display); font-size: 24px; line-height: 1; color: #fff; letter-spacing: 0.03em; }
.next-card {
  margin: 0 0 20px;
  padding: 14px 16px;
  border-left: 2px solid var(--orange);
  background: linear-gradient(90deg, rgba(255, 130, 30, 0.1), transparent);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.next-card span { font-size: 8px; letter-spacing: 0.22em; color: #ff9a54; font-weight: 800; }
.next-card strong { font-family: var(--display); font-size: 28px; letter-spacing: 0.04em; color: #fff; line-height: 1; }
.next-card em { font-style: normal; font-size: 9px; letter-spacing: 0.16em; color: #9aa7c9; }
.defeat-panel { border-color: rgba(255, 70, 100, 0.35); }
.defeat-panel h2 { color: #ff5d75; text-shadow: 3px 4px 0 #000, 0 0 30px rgba(255, 50, 80, 0.3); }
.defeat-line, .complete-line {
  margin: 0 0 18px;
  color: #aeb9d6;
  font-size: 11px;
  line-height: 1.6;
  font-style: italic;
}
.complete-panel { border-color: rgba(255, 225, 120, 0.5); }
.complete-panel h2 em { background: linear-gradient(180deg, #ffffff, #cfe7ff 50%, #7da8ff); -webkit-background-clip: text; background-clip: text; }
.complete-line { margin-top: 18px; }

/* ============================ OVERLAYS ============================= */
#enemy-card {
  position: absolute;
  left: 50%;
  top: 34%;
  transform: translate(-50%, -50%);
  z-index: 25;
  width: min(760px, 92vw);
  text-align: center;
  pointer-events: none;
  opacity: 0;
}
#enemy-card.show { animation: enemyCard 3s ease forwards; }
@keyframes enemyCard {
  0% { opacity: 0; transform: translate(-50%, -46%) scale(0.96); }
  10% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -53%) scale(1.02); }
}
.ec-line { height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 190, 70, 0.75), transparent); margin: 12px auto; width: 78%; }
.ec-stage { font-size: 9px; letter-spacing: 0.34em; color: var(--orange); font-weight: 800; }
.ec-name {
  font-family: var(--display);
  font-size: clamp(54px, 9vw, 116px);
  line-height: 0.9;
  letter-spacing: 0.02em;
  color: #fff;
  text-shadow: 0 0 40px rgba(255, 90, 60, 0.55), 5px 6px 0 #000;
  margin: 6px 0 0;
  transform: skewX(-4deg);
}
.ec-title { margin-top: 4px; font-size: 11px; letter-spacing: 0.3em; color: #ff9d7c; font-weight: 800; }
.ec-quote { margin-top: 14px; font-size: 13px; font-style: italic; color: #d6ddef; text-shadow: 1px 1px 3px #000; }

#announce {
  position: absolute;
  left: 50%;
  top: 44%;
  transform: translate(-50%, -50%) skewX(-6deg);
  z-index: 24;
  text-align: center;
  pointer-events: none;
  opacity: 0;
}
#announce.show { animation: announcePop 2s cubic-bezier(.2,.8,.2,1) forwards; }
@keyframes announcePop {
  0% { opacity: 0; transform: translate(-50%, -50%) skewX(-6deg) scale(1.6); filter: blur(4px); }
  12% { opacity: 1; transform: translate(-50%, -50%) skewX(-6deg) scale(1); filter: blur(0); }
  72% { opacity: 1; transform: translate(-50%, -50%) skewX(-6deg) scale(1.02); }
  100% { opacity: 0; transform: translate(-50%, -54%) skewX(-6deg) scale(1.06); }
}
#announce-main {
  font-family: var(--display);
  font-size: clamp(54px, 9vw, 126px);
  line-height: 0.86;
  letter-spacing: 0.02em;
  color: #fff;
  -webkit-text-stroke: 1px rgba(255, 240, 170, 0.55);
  text-shadow: 0 0 34px rgba(255, 170, 40, 0.75), 4px 6px 0 #3a1000, 8px 10px 24px rgba(0,0,0,0.8);
  background: linear-gradient(180deg, #fffef2 0%, #ffe782 48%, #ff9a22 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
#announce-sub {
  margin-top: 6px;
  font-size: clamp(10px, 1.4vw, 16px);
  font-weight: 800;
  letter-spacing: 0.28em;
  color: #ffe8a8;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 #000, 0 0 18px rgba(255, 160, 30, 0.5);
}

#toast {
  position: absolute;
  left: 50%;
  bottom: 24%;
  transform: translateX(-50%) translateY(10px);
  z-index: 26;
  padding: 9px 18px;
  background: linear-gradient(90deg, rgba(12, 16, 34, 0.94), rgba(22, 18, 16, 0.94));
  border: 1px solid rgba(255, 200, 80, 0.32);
  color: #ffe6a8;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}
#toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ============================ RESPONSIVE =========================== */
@media (max-width: 900px) {
  .title-screen { background: linear-gradient(0deg, rgba(4,5,14,0.95) 12%, rgba(4,5,14,0.45) 58%, rgba(4,5,14,0.55)); justify-content: center; text-align: center; padding-left: 24px; }
  .title-wrap { width: min(620px, 94vw); display: flex; flex-direction: column; align-items: center; }
  .kicker { justify-content: center; }
  .title-actions { justify-content: center; }
  .title-meta { justify-content: center; flex-wrap: wrap; }
  .sound-btn { margin-left: 0; }
  .help-grid { grid-template-columns: 1fr; }
  .tech-grid { grid-template-columns: repeat(2, 1fr); }
  .player-hud { width: min(360px, 48vw); }
  #hint-area .desktop-hint { display: none; }
  #hint-area .touch-hint { display: inline; }
}
@media (max-width: 700px) {
  .panel { padding: 30px 22px; }
  .stats { grid-template-columns: 1fr 1fr; }
  .tech-grid { grid-template-columns: 1fr; }
  .title-actions .btn { min-width: 130px; padding: 13px 22px; font-size: 19px; }
  .tagline { margin: 16px 0 22px; letter-spacing: 0.2em; }
  #combo { top: 38%; }
}
@media (max-height: 620px) {
  .logo-main { font-size: clamp(50px, 10vw, 96px); }
  .tagline { margin: 12px 0 18px; }
  .title-meta { margin-top: 16px; }
  .panel { padding: 24px 28px; }
  .panel h2 { font-size: 40px; }
  .help-grid { margin: 14px 0 18px; gap: 14px 26px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; }
}

import { WORLD, FORMS, formatNumber } from './data.js'
import { GROUND, GRAVITY, bodyBox, overlap, clamp, rand, sign } from './game.js'

export const combatMethods = {
  stepFighterPhysics(f, dt) {
    if (!f) return
    const wasAir = !f.grounded
    if (!f.grounded) {
      f.vy += GRAVITY * dt
      f.y += f.vy * dt
      if (f.y >= GROUND) {
        f.y = GROUND
        f.vy = 0
        f.grounded = true
        f.jumps = 0
        if (wasAir && !f.dead) {
          this.burst(f.x, GROUND - 2, 8, { colors: ['#cdb99c', '#8d7a63'], speed: 140, size: 4, life: 0.35, gravity: 260, dir: Math.PI / 2, spread: 1.7 })
          if (f.kind === 'player' && f.state === 'jump') f.state = 'idle'
        }
      }
    }
    f.x += f.vx * dt
    if (f.grounded) f.vx *= Math.pow(0.18, dt)
    else f.vx *= Math.pow(0.55, dt)
    if (f.x < WORLD.left + 20) { f.x = WORLD.left + 20; f.vx = Math.abs(f.vx) * 0.2 }
    if (f.x > WORLD.right - 20) { f.x = WORLD.right - 20; f.vx = -Math.abs(f.vx) * 0.2 }
    if (f.y > GROUND) { f.y = GROUND; f.vy = 0; f.grounded = true }
    if (f.hitFlash > 0) f.hitFlash -= dt
    if (f.guardFlash > 0) f.guardFlash -= dt
    if (f.formFx > 0) f.formFx -= dt
    if (f.koT !== undefined) f.koT += dt
  },

  updateCombat(dt) {
    const s = this.s
    for (let i = s.hitboxes.length - 1; i >= 0; i--) {
      const h = s.hitboxes[i]
      h.life -= dt
      if (h.life <= 0) { s.hitboxes.splice(i, 1); continue }
      const target = h.side === 'player' ? s.enemy : s.player
      if (!target || target.dead) continue
      const box = { x: h.x - h.w / 2, y: h.y - h.h / 2, w: h.w, h: h.h }
      if (overlap(box, bodyBox(target))) {
        const hit = this.damageFighter(target, h.damage, {
          source: h.owner, stun: h.stun, knock: h.knock, lift: h.lift,
          crit: h.crit, unblockable: h.unblockable, aoe: h.aoe
        })
        if (hit && !h.pierce) s.hitboxes.splice(i, 1)
      }
    }
    for (let i = s.projectiles.length - 1; i >= 0; i--) {
      const p = s.projectiles[i]
      p.life -= dt
      p.trailTimer = (p.trailTimer || 0) - dt
      p.vy += (p.gravity || 0) * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.spin = (p.spin || 0) + dt * 8
      if (p.trailTimer <= 0) {
        p.trailTimer = 0.025
        this.burst(p.x, p.y, 1, { colors: [p.color, p.color2 || '#ffffff'], speed: 30, size: p.r * 0.8, life: 0.28, gravity: -15, glow: true })
      }
      const target = p.side === 'player' ? s.enemy : s.player
      let hit = false
      if (target && !target.dead) {
        const tb = bodyBox(target)
        if (p.x + p.r > tb.x && p.x - p.r < tb.x + tb.w && p.y + p.r > tb.y && p.y - p.r < tb.y + tb.h) {
          this.damageFighter(target, p.damage, {
            source: p.owner, stun: p.stun || 0.32, knock: p.knock || 180,
            unblockable: p.unblockable, crit: p.crit
          })
          hit = true
        }
      }
      const groundHit = p.y + p.r >= GROUND && p.kind !== 'spirit'
      if (hit || p.life <= 0 || groundHit || p.x < WORLD.left - 100 || p.x > WORLD.right + 100) {
        if (p.explode) this.projectileExplosion(p)
        s.projectiles.splice(i, 1)
      }
    }
    for (let i = s.beams.length - 1; i >= 0; i--) {
      const b = s.beams[i]
      b.life -= dt
      b.tick -= dt
      const o = b.owner
      if (!o) { s.beams.splice(i, 1); continue }
      b.x = o.x + o.facing * 56
      b.y = o.y - 126
      b.dir = o.facing
      if (o.hitstun > 0.12 || o.dead) b.life = Math.min(b.life, 0.08)
      const target = b.side === 'player' ? s.enemy : s.player
      if (target && !target.dead && b.tick <= 0) {
        const tb = bodyBox(target)
        const inFront = (target.x - b.x) * b.dir > -18
        const vert = tb.y < b.y + b.height / 2 && tb.y + tb.h > b.y - b.height / 2
        if (inFront && vert) {
          b.tick = 0.115
          this.damageFighter(target, b.damage, {
            source: o, stun: b.stun || 0.22, knock: b.knock || 80,
            unblockable: false, sound: b.firstTick ? 'beam' : 'hit'
          })
          b.firstTick = false
          this.burst(b.x + b.dir * 60, b.y + rand(-b.height / 3, b.height / 3), 4, {
            colors: [b.color, '#ffffff'], speed: 260, size: 5, life: 0.25, glow: true, dir: b.dir > 0 ? 0 : Math.PI, spread: 1.1
          })
        }
      }
      if (b.life <= 0) {
        this.ring(b.x + b.dir * 60, b.y, { max: 120, life: 0.3, color: b.color, width: 4 })
        s.beams.splice(i, 1)
      }
    }
    for (let i = s.telegraphs.length - 1; i >= 0; i--) {
      const t = s.telegraphs[i]
      t.t += dt
      if (t.t >= t.max) {
        if (!t.fired) {
          t.fired = true
          const target = t.side === 'player' ? s.enemy : s.player
          if (target && !target.dead) {
            const tb = bodyBox(target)
            if (tb.x < t.x + t.radius && tb.x + tb.w > t.x - t.radius) {
              this.damageFighter(target, t.damage, {
                source: t.owner, stun: t.stun || 0.4, knock: t.knock || 260,
                unblockable: t.unblockable, crit: false
              })
            }
          }
          this.burst(t.x, GROUND - 12, 34, { colors: [t.color, '#ffffff', '#ffd28a'], speed: 480, size: 6, life: 0.8, gravity: 300, floor: GROUND })
          this.ring(t.x, GROUND - 8, { max: t.radius, life: 0.65, color: t.color, width: 8 })
          this.ring(t.x, GROUND - 8, { max: t.radius * 0.72, life: 0.45, color: '#ffffff', width: 3 })
          this.shake(20)
          this.audio.explosion()
        }
        if (t.t >= t.max + 0.2) s.telegraphs.splice(i, 1)
      }
    }
  },

  spawnHitbox(owner, opts) {
    const dir = owner.facing
    const scale = owner.scale || 1
    const h = {
      owner, side: owner.kind, life: opts.life || 0.12,
      x: opts.x ?? owner.x + dir * (opts.range || 84) * scale,
      y: opts.y ?? owner.y - (opts.heightY || 128) * scale,
      w: (opts.w || 100) * scale, h: (opts.h || 84) * scale,
      damage: opts.damage, stun: opts.stun, knock: opts.knock, lift: opts.lift,
      crit: !!opts.crit, unblockable: !!opts.unblockable, pierce: !!opts.pierce
    }
    this.s.hitboxes.push(h)
    return h
  },

  spawnProjectile(owner, opts) {
    const dir = opts.dir ?? owner.facing
    const p = {
      owner, side: owner.kind, x: opts.x, y: opts.y,
      vx: opts.vx ?? dir * 900, vy: opts.vy ?? 0,
      r: opts.r || 16, damage: opts.damage, color: opts.color || '#69e9ff',
      color2: opts.color2 || '#ffffff', life: opts.life || 2.4,
      gravity: opts.gravity || 0, kind: opts.kind || 'ki',
      stun: opts.stun, knock: opts.knock, explode: opts.explode || 0,
      unblockable: !!opts.unblockable, crit: !!opts.crit, spin: 0, trailTimer: 0
    }
    this.s.projectiles.push(p)
    this.burst(p.x, p.y, 6, { colors: [p.color, p.color2], speed: 130, size: 5, life: 0.3, glow: true })
    return p
  },

  spawnBeam(owner, opts) {
    const b = {
      owner, side: owner.kind, x: owner.x + owner.facing * 56, y: owner.y - 126,
      dir: owner.facing, life: opts.life || 0.72, maxLife: opts.life || 0.72,
      tick: 0, firstTick: true, damage: opts.damage,
      color: opts.color || '#69e9ff', color2: opts.color2 || '#ffffff',
      width: opts.width || 52, height: opts.height || 68,
      stun: opts.stun || 0.2, knock: opts.knock || 100
    }
    this.s.beams.push(b)
    this.shake(12)
    this.ring(b.x, b.y, { max: 100, life: 0.35, color: b.color, width: 5 })
    this.burst(b.x, b.y, 22, { colors: [b.color, b.color2], speed: 360, size: 5, life: 0.45, glow: true, dir: owner.facing > 0 ? 0 : Math.PI, spread: 1.2 })
    return b
  },

  spawnTelegraph(owner, opts) {
    this.s.telegraphs.push({
      owner, side: owner.kind, x: opts.x ?? owner.x, y: GROUND,
      radius: opts.radius || 260, t: 0, max: opts.time || 1.2,
      damage: opts.damage, color: opts.color || '#ff6450',
      stun: opts.stun, knock: opts.knock, unblockable: !!opts.unblockable,
      label: opts.label || null, fired: false
    })
  },

  damageFighter(target, raw, opts = {}) {
    const s = this.s
    if (!target || target.dead || target.invuln > 0 || s.finish) return false
    const source = opts.source
    let dmg = Math.max(1, raw)
    let blocked = false
    if (target.blocking && target.grounded && !opts.unblockable) {
      const fromFront = !source || sign(source.x - target.x) === target.facing || target.kind === 'player'
      if (fromFront) { blocked = true; dmg *= 0.16 }
    }
    if (opts.crit) dmg *= 1.9
    const dir = source ? sign(target.x - source.x) : -target.facing
    let dodged = false
    if (target.kind === 'player' && !blocked && !opts.unblockable) {
      const form = FORMS[target.form]
      if (target.form >= 5 && target.dodgeCd <= 0 && Math.random() < form.dodge) {
        dodged = true
        target.invuln = Math.max(target.invuln, 0.38)
        target.dodgeCd = 1.35
        this.afterimage(target)
        this.burst(target.x, target.y - 105, 14, { colors: [form.aura2, '#ffffff'], speed: 240, size: 4, life: 0.4, glow: true })
        this.textPop(target.x, target.y - 218, 'EVADED', form.aura2, 15)
        this.audio.teleport()
      }
    }
    if (!dodged) {
      if (target.kind === 'player') {
        const form = FORMS[target.form]
        dmg /= form.defense
        target.hp -= dmg
        target.power = Math.min(100, target.power + dmg * 0.035)
        target.spirit = Math.min(100, target.spirit + dmg * 0.018)
        s.combo = 0
      } else {
        target.hp -= dmg
        s.damageDealt += dmg
        s.fightDamage += dmg
        s.combo++
        s.comboTimer = 2.3
        s.maxCombo = Math.max(s.maxCombo, s.combo)
        const p = s.player
        if (p) {
          p.power = Math.min(100, p.power + 2.1 + Math.min(4, s.combo * 0.12))
          p.spirit = Math.min(100, p.spirit + 0.75 + Math.min(2.4, s.combo * 0.05))
        }
        target.recoil = 0.25
      }
      target.hitFlash = 0.12
      target.hp = Math.max(0, target.hp)
      if (!blocked) {
        target.hitstun = Math.max(target.hitstun, opts.stun ?? 0.25)
        target.state = 'hurt'
        target.stateT = 0
        target.anim = 'hurt'
        target.animT = 0
        target.vx = dir * (opts.knock ?? 140)
        if (opts.lift) target.vy -= opts.lift
        target.blocking = false
        if (target.kind === 'enemy') {
          target.special = null
          target.attackName = null
        }
      } else {
        target.hitstun = Math.max(target.hitstun, 0.08)
        target.vx += dir * 34
        target.guardFlash = 0.2
      }
      const hy = target.y - 108 * (target.scale || 1)
      const hx = target.x - dir * 8
      if (blocked) {
        this.burst(hx, hy, 9, { colors: ['#8fdcff', '#ffffff', '#3a8bff'], speed: 250, size: 4, life: 0.3, glow: true })
        this.ring(hx, hy, { max: 48, life: 0.26, color: '#83d8ff', width: 3 })
        this.textPop(hx, hy - 28, 'GUARD', '#9fe6ff', 12)
        this.audio.block()
        this.s.hitstop = Math.max(s.hitstop, 0.025)
        this.shake(4)
      } else {
        this.burst(hx, hy, opts.crit ? 20 : 12, {
          colors: [target.kind === 'enemy' ? '#ffcf5a' : '#ff6470', '#ffffff', opts.crit ? '#ffe98a' : '#ffb15a'],
          speed: 320, size: 5, life: 0.35, glow: true
        })
        this.ring(hx, hy, { max: opts.crit ? 80 : 46, life: 0.28, color: opts.crit ? '#ffe98a' : '#ffb66a', width: opts.crit ? 5 : 3 })
        this.textPop(hx + rand(-12, 12), hy - 16, (opts.crit ? 'CRIT ' : '') + Math.round(dmg), opts.crit ? '#ffe066' : '#ffffff', opts.crit ? 21 : 15)
        this.audio[opts.sound === 'beam' ? 'beam' : opts.crit ? 'heavy' : 'hit']()
        this.s.hitstop = Math.max(s.hitstop, opts.crit ? 0.09 : Math.min(0.075, 0.03 + dmg / 3000))
        this.shake(opts.crit ? 14 : 7)
      }
      if (opts.crit && source && source.kind === 'player') source.critWindow = 0
      if (target.hp <= 0) this.knockOut(target, source)
    }
    return !dodged
  },

  knockOut(target, source) {
    const s = this.s
    if (target.dead) return
    target.dead = true
    target.state = 'ko'
    target.anim = 'ko'
    target.koT = 0
    target.hitstun = 999
    target.invuln = 999
    target.hp = 0
    target.blocking = false
    target.vx = sign(target.x - (source?.x ?? target.x)) * 300
    target.vy = -430
    target.grounded = false
    this.audio.ko()
    this.shake(30)
    this.flash('#ffffff', 0.55, 3)
    this.burst(target.x, target.y - 105, 54, {
      colors: target.kind === 'enemy' ? ['#ffe066', '#ff9a3c', '#ffffff'] : ['#ff5a70', '#ffb0b8', '#ffffff'],
      speed: 520, size: 6, life: 1, gravity: 160, floor: GROUND
    })
    this.ring(target.x, target.y - 100, { max: 230, life: 0.8, color: target.kind === 'enemy' ? '#ffe066' : '#ff5a70', width: 8 })
    s.slowmo = 1.35
    s.finishTimer = 3.2
    if (target.kind === 'enemy') {
      s.finish = 'victory'
      this.announce('K.O.', `${target.name} DEFEATED`, 2.5)
      if (s.player) {
        s.player.state = 'victory'
        s.player.vx = 0
      }
    } else {
      s.finish = 'defeat'
      this.announce('K.O.', 'YOUR KI HAS FADED', 2.5)
      if (s.enemy) s.enemy.state = 'victory'
    }
  },

  projectileExplosion(p) {
    const radius = p.explode
    this.ring(p.x, p.y, { max: radius, life: 0.65, color: p.color, width: 9 })
    this.ring(p.x, p.y, { max: radius * 0.62, life: 0.45, color: '#ffffff', width: 4 })
    this.burst(p.x, p.y, 40, { colors: [p.color, p.color2, '#ffffff', '#ffd28a'], speed: 500, size: 7, life: 0.9, gravity: 180, glow: true })
    this.flash(p.color, 0.25, 5)
    this.shake(20)
    this.audio.explosion()
    const s = this.s
    const target = p.side === 'player' ? s.enemy : s.player
    if (target && !target.dead) {
      const tb = bodyBox(target)
      const cx = clamp(p.x, tb.x, tb.x + tb.w)
      const cy = clamp(p.y, tb.y, tb.y + tb.h)
      const d = Math.hypot(cx - p.x, cy - p.y)
      if (d < radius) {
        this.damageFighter(target, p.damage * 0.7, {
          source: p.owner, stun: 0.5, knock: 320, lift: 160, unblockable: false
        })
      }
    }
  },

  burst(x, y, count, opts = {}) {
    const colors = opts.colors || ['#ffffff']
    const baseAngle = opts.dir ?? -Math.PI / 2
    const spread = opts.spread ?? Math.PI * 2
    for (let i = 0; i < count; i++) {
      const ang = baseAngle + rand(-spread / 2, spread / 2)
      const speed = (opts.speed || 220) * rand(0.25, 1)
      const life = (opts.life || 0.5) * rand(0.55, 1.15)
      this.s.particles.push({
        x: x + rand(-4, 4), y: y + rand(-4, 4),
        vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
        life, maxLife: life, size: (opts.size || 4) * rand(0.6, 1.3),
        color: colors[(Math.random() * colors.length) | 0],
        gravity: opts.gravity || 0, drag: opts.drag ?? 0.55,
        glow: opts.glow !== false, floor: opts.floor, type: opts.type || 'spark'
      })
    }
  },

  ring(x, y, opts = {}) {
    const life = opts.life || 0.5
    this.s.rings.push({
      x, y, t: 0, life, maxLife: life,
      max: opts.max || 90, color: opts.color || '#ffd23f',
      width: opts.width || 4, fill: !!opts.fill
    })
  },

  textPop(x, y, text, color = '#fff', size = 16) {
    this.s.texts.push({ x, y, text, color, size, life: 0.85, maxLife: 0.85, vy: -90 })
  },

  afterimage(f) {
    this.s.afterimages.push({
      x: f.x, y: f.y, facing: f.facing, scale: f.scale, form: f.form,
      kind: f.kind, look: f.look, def: f.def, state: f.state, anim: f.anim, animT: f.animT,
      stateT: f.stateT, hp: f.hp, maxHp: f.maxHp, dead: false, blocking: f.blocking,
      grounded: f.grounded, hitFlash: 0, formFx: 0, koT: 0, life: 0.32, maxLife: 0.32
    })
  },

  speedLines(count = 8) {
    for (let i = 0; i < count; i++) {
      this.s.speedlines.push({
        x: rand(WORLD.left, WORLD.right), y: rand(240, GROUND - 30),
        len: rand(70, 200), angle: rand(-0.12, 0.12), life: rand(0.2, 0.45), maxLife: 0.45,
        color: '#ffffff'
      })
    }
  },

  shake(amount) {
    this.s.camera.shake = Math.max(this.s.camera.shake, amount)
  }
}

import { WORLD, FORMS, TECHNIQUES, formatNumber } from './data.js'
import { GROUND, JUMP_V, clamp, rand, sign } from './game.js'

const approach = (v, target, amount) => v < target ? Math.min(v + amount, target) : Math.max(v - amount, target)

export const playerMethods = {
  updatePlayer(dt) {
    const s = this.s
    const p = s.player
    if (!p) return
    p.stateT += dt
    p.animT += dt
    if (p.invuln > 0) p.invuln -= dt
    if (p.hitstun > 0) p.hitstun -= dt
    if (p.dashCd > 0) p.dashCd -= dt
    if (p.dodgeCd > 0) p.dodgeCd -= dt
    if (p.critWindow > 0) p.critWindow -= dt
    for (let i = 0; i < p.cooldowns.length; i++) if (p.cooldowns[i] > 0) p.cooldowns[i] -= dt

    if (p.dead) {
      p.state = 'ko'
      this.stepFighterPhysics(p, dt)
      if (p.grounded && Math.random() < dt * 14) {
        this.burst(p.x + rand(-40, 40), GROUND - 4, 1, {
          colors: ['#8a8172', '#4b4741'], speed: 35, size: 5, life: 0.8, gravity: -30, glow: false
        })
      }
      return
    }

    const form = FORMS[p.form]

    if (s.finish) {
      p.state = 'victory'
      p.vx = 0
      p.blocking = false
      this.stepFighterPhysics(p, dt)
      return
    }

    if (p.form > 0 && Math.random() < dt * (5 + p.form * 2.4)) {
      this.burst(
        p.x + rand(-26, 26), p.y - rand(18, 180 * p.scale),
        1, { colors: [form.aura, form.aura2], speed: rand(20, 65), size: rand(2.5, 5), life: rand(0.35, 0.75), gravity: -rand(80, 180), glow: true, drag: 0.8 }
      )
    }
    if (p.formFx > 0 && Math.random() < dt * 40) {
      this.burst(p.x + rand(-50, 50), p.y - rand(0, 210), 1, {
        colors: [form.aura, '#ffffff'], speed: rand(60, 220), size: rand(3, 7), life: rand(0.4, 0.9), gravity: rand(-60, 60), glow: true
      })
    }

    if (p.hitstun > 0) {
      p.state = 'hurt'
      p.blocking = false
      p.anim = 'hurt'
      this.stepFighterPhysics(p, dt)
      if (p.hitstun <= 0) { p.state = 'idle'; p.anim = 'idle'; p.animT = 0 }
      return
    }

    if (p.dashT > 0) {
      p.dashT -= dt
      p.state = 'dash'
      p.anim = 'dash'
      p.invuln = Math.max(p.invuln, 0.06)
      p.afterimageCd -= dt
      if (p.afterimageCd <= 0) {
        p.afterimageCd = 0.035
        this.afterimage(p)
      }
      this.stepFighterPhysics(p, dt)
      if (p.dashT <= 0) { p.state = 'idle'; p.anim = 'idle'; p.animT = 0 }
      return
    }

    if (p.state === 'transform') {
      p.vx = 0
      p.blocking = false
      this.stepFighterPhysics(p, dt)
      if (p.stateT > 0.8) { p.state = 'idle'; p.anim = 'idle'; p.animT = 0 }
      return
    }

    if (p.state === 'beamCharge') {
      p.beamHold += dt
      p.vx *= Math.pow(0.02, dt)
      p.facing = sign(s.enemy.x - p.x)
      const handX = p.x + p.facing * 46
      const handY = p.y - 126
      if (Math.random() < dt * 55) {
        this.burst(handX + rand(-14, 14), handY + rand(-14, 14), 1, {
          colors: [form.aura, form.aura2, '#ffffff'], speed: rand(60, 170), size: rand(3, 6), life: 0.3, glow: true,
          dir: p.facing > 0 ? Math.PI : 0, spread: 1.5
        })
      }
      if (p.beamHold >= 1.15) this.firePlayerBeam()
      this.stepFighterPhysics(p, dt)
      return
    }

    if (p.state === 'beam') {
      p.beamT -= dt
      p.anim = 'beam'
      p.vx *= Math.pow(0.02, dt)
      p.facing = sign(s.enemy.x - p.x)
      if (p.beamT <= 0) { p.state = 'idle'; p.anim = 'idle'; p.animT = 0 }
      this.stepFighterPhysics(p, dt)
      return
    }

    if (p.state === 'attack') {
      p.attackT += dt
      p.vx *= Math.pow(0.03, dt)
      if (!p.attackHit && p.attackT >= p.attackHitAt) {
        p.attackHit = true
        this.spawnPlayerMelee(p.attackKind, p.chain)
      }
      if (p.attackT >= p.attackDuration) {
        p.state = 'idle'
        p.anim = 'idle'
        p.animT = 0
      }
      this.stepFighterPhysics(p, dt)
      return
    }

    if (p.state === 'cast') {
      p.castT -= dt
      p.vx *= Math.pow(0.1, dt)
      if (p.castT <= 0) { p.state = 'idle'; p.anim = 'idle'; p.animT = 0 }
      this.stepFighterPhysics(p, dt)
      return
    }

    if (p.state === 'skill') {
      this.updatePlayerSkill(dt)
      this.stepFighterPhysics(p, dt)
      return
    }

    p.blocking = false
    const axis = this.input.x
    p.facing = sign(s.enemy.x - p.x)

    if (this.input.charge && p.grounded && Math.abs(axis) < 0.3) {
      p.state = 'charge'
      p.anim = 'charge'
      p.chargeT += dt
      p.vx = 0
      p.power = Math.min(100, p.power + 30 * dt)
      p.ki = Math.min(p.maxKi, p.ki + 29 * dt)
      if (Math.random() < dt * 75) {
        this.burst(p.x + rand(-34, 34), p.y - rand(0, 200), 1, {
          colors: [form.aura, form.aura2, '#ffffff'], speed: rand(30, 150), size: rand(2, 6),
          life: rand(0.3, 0.8), gravity: -rand(80, 260), glow: true, drag: 0.8
        })
      }
      if (p.power >= 99.5 && !s.readyNotified) {
        s.readyNotified = true
        this.toast(this.isTouch() ? 'POWER FULL — TAP ASCEND' : 'POWER FULL — PRESS Q TO ASCEND', 2.4)
        this.ring(p.x, p.y - 100, { max: 130, life: 0.45, color: form.aura2, width: 4 })
        this.audio.ui()
      }
      this.stepFighterPhysics(p, dt)
      return
    }

    if (this.input.guard && p.grounded) {
      p.state = 'guard'
      p.anim = 'guard'
      p.blocking = true
      p.vx = approach(p.vx, 0, 2400 * dt)
      this.stepFighterPhysics(p, dt)
      return
    }

    const speed = 360 * form.speed
    if (Math.abs(axis) > 0.05) {
      p.vx = axis * speed
      p.state = p.grounded ? 'walk' : 'jump'
      p.anim = p.grounded ? 'walk' : 'jump'
    } else {
      p.vx = approach(p.vx, 0, 2600 * dt)
      p.state = p.grounded ? 'idle' : 'jump'
      p.anim = p.grounded ? 'idle' : 'jump'
    }
    p.ki = Math.min(p.maxKi, p.ki + form.kiRegen * dt)
    if (p.power < 100) p.power = Math.min(100, p.power + 0.22 * dt)
    this.stepFighterPhysics(p, dt)
  },

  playerLight() {
    const p = this.s.player
    if (!p || this.s.mode !== 'fight' || this.s.finish) return
    if (p.hitstun > 0 || p.dead) return
    const busy = ['dash', 'beam', 'skill', 'transform', 'hurt', 'ko', 'cast'].includes(p.state)
    if (busy) return
    if (p.state === 'attack' && p.attackT < p.attackDuration * 0.42) return
    const chain = p.state === 'attack' || (p.lastAttackAt && this.s.time - p.lastAttackAt < 0.65)
      ? ((p.chain || 0) + 1) % 3 : 0
    p.chain = chain
    p.lastAttackAt = this.s.time
    p.blocking = false
    p.facing = sign(this.s.enemy.x - p.x)
    p.state = 'attack'
    p.anim = chain === 2 ? 'kick' : 'punch'
    p.animT = 0
    p.stateT = 0
    p.attackKind = 'light'
    p.attackT = 0
    p.attackDuration = chain === 2 ? 0.31 : 0.25
    p.attackHitAt = chain === 2 ? 0.11 : 0.06
    p.attackHit = false
    p.vx = p.facing * 90
    this.audio.whoosh()
  },

  playerHeavy() {
    const p = this.s.player
    if (!p || this.s.mode !== 'fight' || this.s.finish) return
    if (p.hitstun > 0 || p.dead) return
    const busy = ['dash', 'beam', 'skill', 'transform', 'hurt', 'ko', 'cast'].includes(p.state)
    if (busy) return
    if (p.state === 'attack' && p.attackT < p.attackDuration * 0.5) return
    p.blocking = false
    p.facing = sign(this.s.enemy.x - p.x)
    p.state = 'attack'
    p.anim = 'heavy'
    p.animT = 0
    p.stateT = 0
    p.attackKind = 'heavy'
    p.attackT = 0
    p.attackDuration = 0.44
    p.attackHitAt = 0.19
    p.attackHit = false
    p.vx = p.facing * 130
    this.audio.whoosh()
  },

  spawnPlayerMelee(kind, chain) {
    const p = this.s.player
    const form = FORMS[p.form]
    const crit = p.critWindow > 0
    if (kind === 'heavy') {
      this.spawnHitbox(p, {
        damage: 64 * form.dmg, range: 96, heightY: 118, w: 128, h: 104,
        stun: 0.44, knock: 300, lift: 90, crit, life: 0.14
      })
      this.ring(p.x + p.facing * 90, p.y - 118, { max: 62, life: 0.24, color: form.aura2, width: 3 })
    } else if (chain === 2) {
      this.spawnHitbox(p, {
        damage: 40 * form.dmg, range: 98, heightY: 118, w: 118, h: 92,
        stun: 0.32, knock: 210, lift: 35, crit, life: 0.13
      })
      this.ring(p.x + p.facing * 92, p.y - 118, { max: 48, life: 0.2, color: form.aura2, width: 2 })
    } else {
      this.spawnHitbox(p, {
        damage: (25 + chain * 4) * form.dmg, range: 85, heightY: 128, w: 96, h: 78,
        stun: 0.24, knock: 130, lif: 0, crit, life: 0.12
      })
    }
  },

  playerJump() {
    const p = this.s.player
    if (!p || this.s.mode !== 'fight' || this.s.finish || p.dead || p.hitstun > 0) return
    if (['beam', 'skill', 'transform', 'ko', 'hurt'].includes(p.state)) return
    if (p.grounded) {
      p.vy = -JUMP_V
      p.grounded = false
      p.jumps = 1
      p.state = 'jump'
      p.anim = 'jump'
      p.animT = 0
      this.audio.jump()
      this.burst(p.x, GROUND - 2, 8, { colors: ['#d8c8a8', '#8c7c62'], speed: 170, size: 4, life: 0.35, gravity: 260, dir: Math.PI / 2, spread: 1.5 })
    } else if (p.jumps < 2) {
      p.vy = -JUMP_V * 0.9
      p.jumps = 2
      p.state = 'jump'
      this.audio.jump()
      this.ring(p.x, p.y - 20, { max: 55, life: 0.32, color: FORMS[p.form].aura2, width: 3 })
      this.burst(p.x, p.y - 10, 10, { colors: [FORMS[p.form].aura, '#ffffff'], speed: 150, size: 3, life: 0.3, dir: Math.PI / 2, spread: 1.6 })
    }
  },

  playerDash() {
    const p = this.s.player
    if (!p || this.s.mode !== 'fight' || this.s.finish) return
    if (!this.canAct(p) || p.dashCd > 0) return
    let dir = this.input.x
    if (Math.abs(dir) < 0.2) dir = p.facing
    dir = sign(dir)
    p.dashT = 0.2
    p.dashCd = 0.72
    p.invuln = Math.max(p.invuln, 0.28)
    p.state = 'dash'
    p.anim = 'dash'
    p.animT = 0
    p.vx = dir * 980
    p.vy = 0
    p.grounded = false
    p.y = Math.min(p.y, GROUND - 8)
    p.facing = dir
    p.afterimageCd = 0
    this.audio.dash()
    this.afterimage(p)
    this.speedLines(10)
    this.burst(p.x, p.y - 110, 14, {
      colors: [FORMS[p.form].aura, '#ffffff'], speed: 280, size: 4, life: 0.3,
      dir: dir > 0 ? Math.PI : 0, spread: 0.8, glow: true
    })
  },

  playerKi() {
    const p = this.s.player
    if (!p || this.s.mode !== 'fight' || this.s.finish) return
    if (!this.canAct(p)) return
    if (p.ki < 8) { this.toast('NOT ENOUGH KI', 1.2); return }
    const form = FORMS[p.form]
    p.ki -= 8
    p.state = 'cast'
    p.castT = 0.19
    p.anim = 'cast'
    p.animT = 0
    p.vx = p.facing * 30
    p.facing = sign(this.s.enemy.x - p.x)
    const crit = p.critWindow > 0
    this.spawnProjectile(p, {
      x: p.x + p.facing * 62, y: p.y - 128,
      vx: p.facing * 1080, r: 15, damage: 28 * form.dmg,
      color: form.aura, color2: form.aura2, stun: 0.28, knock: 165, life: 2.2, crit
    })
    this.audio.ki()
    this.burst(p.x + p.facing * 58, p.y - 128, 9, {
      colors: [form.aura, '#ffffff'], speed: 230, size: 4, life: 0.25,
      dir: p.facing > 0 ? 0 : Math.PI, spread: 0.9, glow: true
    })
  },

  playerBeamStart() {
    const p = this.s.player
    if (!p || this.s.mode !== 'fight' || this.s.finish) return
    if (p.state === 'beamCharge' || p.state === 'beam') return
    if (!this.canAct(p)) return
    if (p.ki < 30) { this.toast('NOT ENOUGH KI FOR KAMEHAMEHA', 1.4); return }
    p.state = 'beamCharge'
    p.anim = 'beamCharge'
    p.animT = 0
    p.stateT = 0
    p.beamHold = 0
    p.beamT = 0
    p.vx = 0
    p.blocking = false
    p.facing = sign(this.s.enemy.x - p.x)
    this.audio.beamCharge()
    this.toast('HOLD TO CHARGE · RELEASE TO FIRE', 1.2)
  },

  playerBeamRelease() {
    const p = this.s.player
    if (!p || p.state !== 'beamCharge') return
    this.firePlayerBeam()
  },

  firePlayerBeam() {
    const p = this.s.player
    if (!p || p.state !== 'beamCharge') return
    const form = FORMS[p.form]
    const ratio = clamp(p.beamHold / 1.15, 0, 1)
    p.ki = Math.max(0, p.ki - 30)
    p.state = 'beam'
    p.anim = 'beam'
    p.animT = 0
    p.stateT = 0
    p.beamT = 0.74
    p.beamFired = true
    p.lastBeamRatio = ratio
    p.vx = -p.facing * 30
    p.facing = sign(this.s.enemy.x - p.x)
    const dmg = (33 + 23 * ratio) * form.dmg
    this.spawnBeam(p, {
      damage: dmg, color: form.aura, color2: form.aura2,
      width: 44 + 34 * ratio, height: 62 + 40 * ratio,
      life: 0.72, stun: 0.2, knock: 120
    })
    this.flash(form.aura2, 0.18 + ratio * 0.2, 4)
    this.audio.beam()
    this.shake(11)
    this.ring(p.x + p.facing * 70, p.y - 126, { max: 95 + ratio * 80, life: 0.35, color: form.aura2, width: 5 })
  },

  playerSkill(index) {
    const s = this.s
    const p = s.player
    if (!p || s.mode !== 'fight' || s.finish || p.dead) return
    const tech = TECHNIQUES[index]
    if (!tech) return
    if (p.form < tech.minForm) {
      this.toast(`${tech.name} UNLOCKS AT ${FORMS[tech.minForm].name}`, 2.3)
      return
    }
    if (p.cooldowns[index] > 0) {
      this.toast(`${tech.name} RECHARGING · ${p.cooldowns[index].toFixed(1)}s`, 1.2)
      return
    }
    if (tech.cost && p.ki < tech.cost) {
      this.toast('NOT ENOUGH KI', 1.2)
      return
    }
    if (tech.spirit && p.spirit < tech.spirit) {
      this.toast(`SPIRIT GAUGE ${Math.round(p.spirit)}% — DEAL DAMAGE TO FILL IT`, 2.2)
      return
    }
    if (!this.canAct(p) && !['charge', 'guard'].includes(p.state)) return
    const form = FORMS[p.form]
    p.facing = sign(s.enemy.x - p.x)
    p.blocking = false
    p.cooldowns[index] = tech.cooldown

    if (tech.id === 'solar') {
      p.ki -= tech.cost
      p.state = 'skill'
      p.skillId = 'solar'
      p.skillT = 0
      p.skillDuration = 0.6
      p.skillDone = false
      p.anim = 'solar'
      p.animT = 0
      p.vx = 0
      this.audio.flash()
      return
    }

    if (tech.id === 'teleport') {
      p.ki -= tech.cost
      const enemy = s.enemy
      this.afterimage(p)
      this.burst(p.x, p.y - 105, 24, { colors: ['#8ad8ff', '#ffffff'], speed: 300, size: 5, life: 0.4, glow: true })
      const behind = clamp(enemy.x + enemy.facing * 112, WORLD.left + 40, WORLD.right - 40)
      p.x = behind
      p.y = GROUND
      p.grounded = true
      p.vy = 0
      p.vx = 0
      p.facing = sign(enemy.x - p.x)
      p.invuln = Math.max(p.invuln, 0.62)
      p.critWindow = 3.4
      p.state = 'idle'
      p.anim = 'idle'
      p.animT = 0
      this.afterimage(p)
      this.burst(p.x, p.y - 105, 28, { colors: ['#8ad8ff', '#ffffff'], speed: 320, size: 5, life: 0.45, glow: true })
      this.audio.teleport()
      this.textPop(p.x, p.y - 220, 'BEHIND YOU', '#8ad8ff', 15)
      this.toast('CRITICAL STRIKE READY', 1.3)
      return
    }

    if (tech.id === 'dragonfist') {
      p.ki -= tech.cost
      p.state = 'skill'
      p.skillId = 'dragonfist'
      p.skillT = 0
      p.skillDuration = 0.66
      p.skillDone = false
      p.anim = 'dragon'
      p.animT = 0
      p.invuln = Math.max(p.invuln, 0.42)
      p.vx = 0
      this.audio.beamCharge()
      this.announce('DRAGON FIST', 'GOLDEN DRAGON STRIKE', 1.3)
      return
    }

    if (tech.id === 'spirit') {
      p.spirit = 0
      p.state = 'skill'
      p.skillId = 'spirit'
      p.skillT = 0
      p.skillDuration = 1.85
      p.skillDone = false
      p.spiritCharge = 0
      p.anim = 'spirit'
      p.animT = 0
      p.invuln = Math.max(p.invuln, 1.2)
      p.vx = 0
      this.audio.spirit()
      this.announce('SPIRIT BOMB', 'LEND ME YOUR ENERGY', 1.8)
      return
    }
  },

  updatePlayerSkill(dt) {
    const s = this.s
    const p = s.player
    const form = FORMS[p.form]
    p.skillT += dt
    if (p.skillId === 'solar') {
      if (!p.skillDone && p.skillT >= 0.13) {
        p.skillDone = true
        this.flash('#fff9c4', 0.95, 3.4)
        this.ring(p.x, p.y - 120, { max: 560, life: 0.55, color: '#fff2a0', width: 18 })
        this.ring(p.x, p.y - 120, { max: 380, life: 0.4, color: '#ffffff', width: 7 })
        this.burst(p.x, p.y - 140, 70, { colors: ['#fff6c2', '#ffe066', '#ffffff'], speed: 640, size: 6, life: 0.65, glow: true })
        this.shake(17)
        this.audio.flash()
        const e = s.enemy
        if (e && !e.dead && Math.abs(e.x - p.x) < 560) {
          this.damageFighter(e, 12 * form.dmg, { source: p, stun: 2.2, knock: 40, sound: 'hit' })
          if (!e.dead) {
            e.state = 'hurt'
            e.hitstun = Math.max(e.hitstun, 2.2)
            e.blocking = false
            e.attackName = null
            e.special = null
          }
          this.textPop(e.x, e.y - 225, 'BLINDED', '#fff2a0', 18)
        }
      }
      if (p.skillT >= p.skillDuration) { p.state = 'idle'; p.skillId = null; p.anim = 'idle'; p.animT = 0 }
      return
    }
    if (p.skillId === 'dragonfist') {
      if (!p.skillDone && p.skillT >= 0.12) {
        p.skillDone = true
        p.vx = p.facing * 900
        p.invuln = Math.max(p.invuln, 0.26)
        const crit = p.critWindow > 0
        this.spawnHitbox(p, {
          damage: 165 * form.dmg, range: 128, heightY: 118, w: 170, h: 118,
          stun: 0.62, knock: 420, lift: 170, crit, life: 0.22, unblockable: false
        })
        this.burst(p.x + p.facing * 30, p.y - 105, 36, {
          colors: ['#ffe066', '#ffb021', '#fff6c2'], speed: 520, size: 6, life: 0.55,
          dir: p.facing > 0 ? 0 : Math.PI, spread: 0.85, glow: true
        })
        this.ring(p.x + p.facing * 80, p.y - 108, { max: 150, life: 0.45, color: '#ffe066', width: 8 })
        this.speedLines(14)
        this.audio.beam()
        this.shake(16)
        if (crit) p.critWindow = 0
      }
      if (p.skillT >= 0.4) p.vx *= Math.pow(0.01, dt)
      if (p.skillT >= p.skillDuration) { p.state = 'idle'; p.skillId = null; p.anim = 'idle'; p.animT = 0 }
      return
    }
    if (p.skillId === 'spirit') {
      if (p.skillT < 1.18) {
        p.spiritCharge = p.skillT / 1.18
        const handX = p.x
        const handY = p.y - 232
        for (let i = 0; i < 2; i++) {
          const ang = rand(0, Math.PI * 2)
          const r = rand(30, 120)
          this.s.particles.push({
            x: handX + Math.cos(ang) * r, y: handY + Math.sin(ang) * r * 0.6,
            vx: -Math.cos(ang) * r * 1.6, vy: -Math.sin(ang) * r * 0.9 - 60,
            life: 0.5, maxLife: 0.5, size: rand(3, 6), color: i ? '#b6f4ff' : '#4b9bff',
            gravity: 0, drag: 0.8, glow: true
          })
        }
      }
      if (!p.skillDone && p.skillT >= 1.18) {
        p.skillDone = true
        this.spawnProjectile(p, {
          x: p.x + p.facing * 30, y: p.y - 210,
          vx: p.facing * 640, vy: -20, r: 66,
          damage: 340 * form.dmg, color: '#9fe8ff', color2: '#ffffff',
          life: 3, explode: 250, kind: 'spirit', stun: 0.9, knock: 500,
          unblockable: false
        })
        this.flash('#c8f4ff', 0.5, 3)
        this.shake(20)
        this.audio.explosion()
        p.vx = -p.facing * 60
      }
      if (p.skillT >= p.skillDuration) { p.state = 'idle'; p.skillId = null; p.anim = 'idle'; p.animT = 0 }
      return
    }
    if (p.skillT >= p.skillDuration) { p.state = 'idle'; p.skillId = null; p.anim = 'idle'; p.animT = 0 }
  }
}

import { WORLD, FORMS } from './data.js'
import { GROUND, GROUND as _G, clamp, rand, sign, choose } from './game.js'

const approach = (v, target, amount) => v < target ? Math.min(v + amount, target) : Math.max(v - amount, target)

export const enemyMethods = {
  updateEnemy(dt) {
    const s = this.s
    const e = s.enemy
    const p = s.player
    if (!e) return
    e.stateT += dt
    e.animT += dt
    if (e.invuln > 0) e.invuln -= dt
    if (e.hitstun > 0) e.hitstun -= dt
    if (e.attackCd > 0) e.attackCd -= dt
    if (e.kiCd > 0) e.kiCd -= dt
    if (e.specialCd > 0) e.specialCd -= dt
    if (e.guardCd > 0) e.guardCd -= dt
    if (e.jumpCd > 0) e.jumpCd -= dt
    if (e.hitFlash > 0) e.hitFlash -= dt
    if (e.guardFlash > 0) e.guardFlash -= dt
    if (e.formFx > 0) e.formFx -= dt
    e.auraPulse += dt

    if (e.dead) {
      e.state = 'ko'
      this.stepFighterPhysics(e, dt)
      if (e.grounded && Math.random() < dt * 12) {
        this.burst(e.x + rand(-50, 50), GROUND - 4, 1, {
          colors: ['#8a8172', '#4b4741'], speed: 32, size: 6, life: 1, gravity: -25, glow: false
        })
      }
      return
    }

    if (s.finish) {
      if (e.state !== 'victory') e.state = 'victory'
      e.vx = 0
      e.blocking = false
      this.stepFighterPhysics(e, dt)
      return
    }

    if (e.def.regen) e.hp = Math.min(e.maxHp, e.hp + e.def.regen * dt)

    if (e.hitstun > 0) {
      e.state = 'hurt'
      e.blocking = false
      e.anim = 'hurt'
      if (e.special) { e.special = null; e.attackName = null }
      this.stepFighterPhysics(e, dt)
      if (e.hitstun <= 0) { e.state = 'idle'; e.anim = 'idle'; e.animT = 0 }
      return
    }

    if (!e.enraged && e.hp < e.maxHp * 0.38) {
      e.enraged = true
      e.damage *= 1.18
      e.speed *= 1.14
      e.attackCd = 0.2
      e.specialCd = 0.7
      e.invuln = Math.max(e.invuln, 0.7)
      e.formFx = 1.2
      e.state = 'transform'
      e.stateT = 0
      this.announce(`${e.name} POWER UP`, 'A DEEPER RESERVE OF POWER', 1.8)
      this.ring(e.x, e.y - 100, { max: 230, life: 0.7, color: e.def.aura, width: 7 })
      this.burst(e.x, e.y - 100, 38, { colors: [e.def.aura, e.def.aura2, '#ffffff'], speed: 420, size: 6, life: 0.8, glow: true })
      this.flash(e.def.aura, 0.3, 4)
      this.shake(16)
      this.audio.transform(4)
      this.stepFighterPhysics(e, dt)
      return
    }

    if (p) e.facing = sign(p.x - e.x)
    else e.facing = -1

    if (e.state === 'transform') {
      e.vx = 0
      this.stepFighterPhysics(e, dt)
      if (e.stateT > 1) { e.state = 'idle'; e.anim = 'idle'; e.animT = 0 }
      return
    }

    if (e.state === 'special') {
      this.updateEnemySpecial(dt)
      this.stepFighterPhysics(e, dt)
      return
    }

    if (e.state === 'attack') {
      e.attackT += dt
      e.vx *= Math.pow(0.02, dt)
      if (!e.attackHit && e.attackT >= e.attackHitAt) {
        e.attackHit = true
        this.spawnEnemyMelee(e.attackKind)
      }
      if (e.attackT >= e.attackDuration) { e.state = 'idle'; e.anim = 'idle'; e.animT = 0 }
      this.stepFighterPhysics(e, dt)
      return
    }

    if (e.state === 'cast') {
      e.castT -= dt
      e.vx *= Math.pow(0.1, dt)
      if (e.castT <= 0) { e.state = 'idle'; e.anim = 'idle'; e.animT = 0 }
      this.stepFighterPhysics(e, dt)
      return
    }

    if (e.state === 'guard') {
      e.guardT -= dt
      e.blocking = true
      e.vx = approach(e.vx, 0, 3000 * dt)
      if (e.guardT <= 0) { e.state = 'idle'; e.blocking = false; e.anim = 'idle'; e.animT = 0 }
      this.stepFighterPhysics(e, dt)
      return
    }

    if (e.state === 'dash') {
      e.dashT -= dt
      e.vx *= Math.pow(0.08, dt)
      if (e.dashT <= 0) { e.state = 'idle'; e.anim = 'idle'; e.animT = 0 }
      this.stepFighterPhysics(e, dt)
      return
    }

    e.blocking = false
    this.updateEnemyAI(dt)
    this.stepFighterPhysics(e, dt)
  },

  updateEnemyAI(dt) {
    const s = this.s
    const e = s.enemy
    const p = s.player
    if (!p || p.dead) return
    const dist = Math.abs(p.x - e.x)
    const dir = sign(p.x - e.x)
    e.facing = dir

    // Desperate evasive hop when the player is charging a beam.
    if (e.grounded && e.jumpCd <= 0 && p.state === 'beamCharge' && dist < 620 && Math.random() < 0.035) {
      e.vy = -860
      e.grounded = false
      e.jumpCd = 2.4
      e.state = 'jump'
      this.burst(e.x, GROUND - 2, 8, { colors: ['#d8c8a8', '#8c7c62'], speed: 160, size: 4, life: 0.3, gravity: 250, dir: Math.PI / 2, spread: 1.5 })
      this.audio.jump()
    }
    if (e.grounded && e.jumpCd <= 0 && s.projectiles.some(pr => pr.side === 'player' && Math.abs(pr.x - e.x) < 260) && Math.random() < 0.06) {
      e.vy = -820
      e.grounded = false
      e.jumpCd = 2.2
      e.state = 'jump'
      this.audio.jump()
    }

    // Guard reaction.
    if (e.guardCd <= 0 && dist < 260 && (p.state === 'attack' || p.state === 'beamCharge') && Math.random() < 0.018 + e.aggression * 0.02) {
      e.state = 'guard'
      e.guardT = 0.5
      e.guardCd = 1.3 + Math.random()
      e.blocking = true
      e.vx = 0
      this.audio.ui()
      return
    }

    if (e.specialCd <= 0 && dist < 980 && Math.random() < 0.35 + e.aggression * 0.2) {
      const attacks = e.def.attacks
      let atk = choose(attacks)
      if (attacks.length > 1 && e.lastSpecial === atk.id) atk = attacks[(attacks.indexOf(atk) + 1) % attacks.length]
      e.lastSpecial = atk.id
      this.useEnemySpecial(atk)
      return
    }

    if (dist < 230 && e.attackCd <= 0) {
      const heavy = Math.random() < 0.24 + e.aggression * 0.14
      this.enemyMelee(heavy ? 'heavy' : 'light')
      return
    }

    if (dist > 250 && e.kiCd <= 0 && Math.random() < 0.12) {
      this.enemyBasicKi()
      return
    }

    let target = 0
    if (dist > 168) target = dir * 315 * e.speed
    else if (dist < 95) target = -dir * 250 * e.speed
    if (dist > 720) target = dir * 390 * e.speed
    if (e.grounded) e.vx = approach(e.vx, target, 2200 * dt)
    else e.vx = approach(e.vx, target * 0.7, 1300 * dt)
    if (Math.abs(target) > 20) {
      e.state = 'walk'
      e.anim = 'walk'
    } else {
      e.state = 'idle'
      e.anim = 'idle'
    }
  },

  enemyMelee(kind) {
    const e = this.s.enemy
    if (!e) return
    e.facing = sign(this.s.player.x - e.x)
    e.state = 'attack'
    e.anim = kind === 'heavy' ? 'heavy' : 'punch'
    e.animT = 0
    e.stateT = 0
    e.attackKind = kind
    e.attackT = 0
    e.attackDuration = kind === 'heavy' ? 0.58 : 0.42
    e.attackHitAt = kind === 'heavy' ? 0.33 : 0.2
    e.attackHit = false
    e.vx = e.facing * (kind === 'heavy' ? 150 : 100)
    e.attackCd = (kind === 'heavy' ? 1.05 : 0.65) + Math.random() * 0.5
    this.audio.whoosh()
  },

  spawnEnemyMelee(kind) {
    const e = this.s.enemy
    if (!e) return
    const dmg = e.damage * (kind === 'heavy' ? 5.8 : 3.5)
    this.spawnHitbox(e, {
      damage: dmg, range: kind === 'heavy' ? 96 : 86,
      heightY: 120, w: kind === 'heavy' ? 130 : 100, h: kind === 'heavy' ? 108 : 82,
      stun: kind === 'heavy' ? 0.5 : 0.28, knock: kind === 'heavy' ? 330 : 160,
      lift: kind === 'heavy' ? 110 : 0, life: 0.14
    })
    this.ring(e.x + e.facing * 92, e.y - 118, {
      max: kind === 'heavy' ? 60 : 42, life: 0.2, color: e.def.accent, width: 3
    })
  },

  enemyBasicKi() {
    const e = this.s.enemy
    const p = this.s.player
    if (!e || !p) return
    e.kiCd = 2.6 + Math.random() * 2.2
    e.state = 'cast'
    e.castT = 0.3
    e.anim = 'cast'
    e.animT = 0
    e.vx = 0
    e.facing = sign(p.x - e.x)
    const dir = e.facing
    this.spawnProjectile(e, {
      x: e.x + dir * 60, y: e.y - 130, vx: dir * 820, vy: rand(-45, 15),
      r: 17, damage: e.damage * 3.1, color: e.def.aura, color2: '#ffffff',
      life: 2.6, stun: 0.32, knock: 180
    })
    this.audio.ki()
  },

  useEnemySpecial(attack) {
    const e = this.s.enemy
    if (!e) return
    e.state = 'special'
    e.special = attack
    e.specialT = 0
    e.specialFired = false
    e.specialHitDone = false
    e.attackName = attack.name
    e.attackT = 0
    e.vx = 0
    e.facing = sign(this.s.player.x - e.x)
    e.specialCd = attack.cd + rand(1.2, 3.4)
    this.audio.beamCharge()
    this.textPop(e.x, e.y - (235 * e.scale), attack.name, attack.color, 12)
    this.ring(e.x, e.y - 110, { max: 100, life: 0.4, color: attack.color, width: 3 })
  },

  updateEnemySpecial(dt) {
    const e = this.s.enemy
    const p = this.s.player
    const a = e.special
    if (!a) { e.state = 'idle'; return }
    e.specialT += dt
    e.vx *= Math.pow(0.02, dt)
    const t = e.specialT

    if (a.type === 'beam') {
      if (!e.specialFired && t >= 1.02) {
        e.specialFired = true
        this.spawnBeam(e, {
          damage: e.damage * 1.55, color: a.color, color2: '#ffffff',
          width: 60, height: 78, life: 0.8, stun: 0.22, knock: 120
        })
        this.flash(a.color, 0.22, 4)
        this.audio.beam()
      }
      if (t >= 2.0) { e.state = 'idle'; e.special = null; e.attackName = null; e.anim = 'idle'; e.animT = 0 }
      return
    }

    if (a.type === 'orb') {
      if (!e.specialFired && t >= 0.48) {
        e.specialFired = true
        this.spawnProjectile(e, {
          x: e.x + e.facing * 62, y: e.y - 145,
          vx: e.facing * 500, vy: -20, r: 46,
          damage: e.damage * 8.2, color: a.color, color2: '#ffffff',
          life: 3.6, explode: 180, stun: 0.7, knock: 380, kind: 'orb'
        })
        this.audio.ki()
        this.shake(8)
      }
      if (t >= 0.95) { e.state = 'idle'; e.special = null; e.attackName = null; e.anim = 'idle'; e.animT = 0 }
      return
    }

    if (a.type === 'volley') {
      if (!e.specialFired && t >= 0.46) {
        e.specialFired = true
        const dir = e.facing
        for (let i = -1; i <= 1; i++) {
          this.spawnProjectile(e, {
            x: e.x + dir * 58, y: e.y - 138 + i * 24,
            vx: dir * 860, vy: i * 150, r: 15,
            damage: e.damage * 3.3, color: a.color, color2: '#ffffff',
            life: 2.6, stun: 0.26, knock: 150
          })
        }
        this.audio.ki()
        this.shake(5)
      }
      if (t >= 1.1) { e.state = 'idle'; e.special = null; e.attackName = null; e.anim = 'idle'; e.animT = 0 }
      return
    }

    if (a.type === 'aoe') {
      if (!e.specialFired && t >= 0.16) {
        e.specialFired = true
        this.spawnTelegraph(e, {
          radius: 310, time: 1.15, damage: e.damage * 8.6,
          color: a.color, stun: 0.7, knock: 430, label: a.name
        })
        this.audio.beamCharge()
      }
      if (t >= 1.55) { e.state = 'idle'; e.special = null; e.attackName = null; e.anim = 'idle'; e.animT = 0 }
      return
    }

    if (a.type === 'dash') {
      if (!e.specialFired && t >= 0.3) {
        e.specialFired = true
        e.vx = e.facing * 1080
        e.invuln = Math.max(e.invuln, 0.35)
        this.speedLines(12)
        this.afterimage(e)
        this.audio.dash()
      }
      if (!e.specialHitDone && t >= 0.38) {
        e.specialHitDone = true
        this.spawnHitbox(e, {
          damage: e.damage * 7.2, range: 105, heightY: 112, w: 145, h: 120,
          stun: 0.62, knock: 420, lift: 180, life: 0.2
        })
        this.burst(e.x + e.facing * 60, e.y - 110, 24, { colors: [a.color, '#ffffff'], speed: 400, size: 5, life: 0.5, glow: true })
      }
      if (t >= 0.95) { e.state = 'idle'; e.special = null; e.attackName = null; e.anim = 'idle'; e.animT = 0 }
    }
  }
}

import { FORMS } from './data.js'

export const eventMethods = {
  updateTouchMode() {
    const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches
    const touch = coarse || ('ontouchstart' in window) || window.innerWidth <= 820
    document.body.classList.toggle('touch', !!touch)
  },

  bindEvents() {
    this.updateTouchMode()
    window.addEventListener('resize', () => this.updateTouchMode())

    this.dom['btn-start'].addEventListener('click', () => this.startGame())
    this.dom['btn-help'].addEventListener('click', () => this.openHelp('title'))
    this.dom['btn-sound'].addEventListener('click', () => this.toggleSound())
    this.dom['btn-resume'].addEventListener('click', () => this.resume())
    this.dom['btn-pause-help'].addEventListener('click', () => this.openHelp('pause'))
    this.dom['btn-quit'].addEventListener('click', () => this.quitToTitle())
    this.dom['btn-next'].addEventListener('click', () => {
      if (this.s.enemyIndex >= 7) {
        this.showComplete()
      } else {
        this.hideScreens()
        this.dom.hud.classList.add('on')
        this.startFight(this.s.enemyIndex + 1)
      }
    })
    this.dom['btn-victory-quit'].addEventListener('click', () => this.quitToTitle())
    this.dom['btn-retry'].addEventListener('click', () => {
      this.hideScreens()
      this.dom.hud.classList.add('on')
      this.startFight(this.s.enemyIndex, true)
    })
    this.dom['btn-defeat-quit'].addEventListener('click', () => this.quitToTitle())
    this.dom['btn-again'].addEventListener('click', () => this.startGame())
    this.dom['btn-complete-quit'].addEventListener('click', () => this.quitToTitle())

    for (const btn of document.querySelectorAll('[data-close="help"]')) {
      btn.addEventListener('click', () => this.closeHelp())
    }

    this.skillButtons.forEach((btn, index) => {
      btn.addEventListener('click', (event) => {
        event.preventDefault()
        this.audio.init()
        if (this.s.mode === 'fight' && !this.s.paused) this.playerSkill(index)
      })
    })

    window.addEventListener('keydown', (event) => this.onKeyDown(event))
    window.addEventListener('keyup', (event) => this.onKeyUp(event))
    window.addEventListener('blur', () => {
      this.keys.clear()
      this.input.stickX = 0
      this.input.stickY = 0
      this.input.chargeTouch = false
      this.input.beamTouch = false
      if (this.s.mode === 'fight' && !this.s.paused) this.pause()
    })
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.s.mode === 'fight' && !this.s.paused) this.pause()
    })
    document.addEventListener('contextmenu', (event) => event.preventDefault())

    this.bindTouch()
  },

  onKeyDown(event) {
    const k = event.key.toLowerCase()
    if (['arrowleft', 'arrowright', 'arrowup', 'arrowdown', ' '].includes(k) || event.code === 'Space') {
      event.preventDefault()
    }
    this.keys.add(k)
    if (event.repeat) return
    if (k === 'm') { this.toggleSound(); return }

    const helpOpen = !this.dom['screen-help'].classList.contains('hidden')
    if (k === 'escape') {
      if (helpOpen) { this.closeHelp(); return }
      if (this.s.paused) { this.resume(); return }
      if (this.s.mode === 'fight') this.pause()
      return
    }
    if (helpOpen) return

    if (this.s.mode === 'title') {
      if (k === 'enter' || k === ' ') { event.preventDefault(); this.startGame() }
      return
    }
    if (this.s.paused) {
      if (k === 'p') this.resume()
      return
    }
    if (this.s.mode !== 'fight') return

    if (k === 'p') { this.pause(); return }
    if (k === 'j' || k === 'z') this.playerLight()
    else if (k === 'k' || k === 'x') this.playerHeavy()
    else if (k === 'l' || k === 'c') this.playerKi()
    else if (k === 'u') this.playerBeamStart()
    else if (k === 'q' || k === 't') this.playerTransform()
    else if (k === 'w' || k === 'arrowup' || k === ' ') this.playerJump()
    else if (k === 'shift') this.playerDash()
    else if (k === '1') this.playerSkill(0)
    else if (k === '2') this.playerSkill(1)
    else if (k === '3') this.playerSkill(2)
    else if (k === '4') this.playerSkill(3)
  },

  onKeyUp(event) {
    const k = event.key.toLowerCase()
    this.keys.delete(k)
    if (k === 'u') this.playerBeamRelease()
  },

  bindTouch() {
    const ring = this.dom['stick-ring']
    const knob = this.dom['stick-knob']
    if (!ring || !knob) return
    let pointerId = null
    let cx = 0
    let cy = 0
    let max = 40

    const start = (event) => {
      event.preventDefault()
      this.audio.init()
      const rect = ring.getBoundingClientRect()
      cx = rect.left + rect.width / 2
      cy = rect.top + rect.height / 2
