() => {
  const g = window.__GAME__
  const out = { steps: [], errors: [], stages: [] }
  const step = (name, ok, detail = '') => {
    out.steps.push({ name, ok, detail })
    if (!ok) out.errors.push(`${name}: ${detail}`)
  }

  g.audio.setEnabled(false)
  g.startGame()
  step('start', g.s.mode === 'intro' && g.s.enemyIndex === 0, `mode=${g.s.mode}`)

  for (let stage = 0; stage < 8; stage++) {
    for (let i = 0; i < 180; i++) g.update(1 / 60)
    const e = g.s.enemy
    step(`stage-${stage + 1}-fight`, g.s.mode === 'fight', `mode=${g.s.mode}`)
    const entry = {
      stage: stage + 1,
      enemy: e.name,
      formAtStart: g.s.player.form,
      maxHp: g.s.player.maxHp,
      hp: Math.round(g.s.player.hp),
      isFinalEnemy: g.s.enemyIndex === 7
    }

    // Transform once per stage, holding the enemy in hitstun so the run is deterministic.
    if (stage < 8) {
      e.hitstun = 999
      g.s.player.power = 100
      g.s.player.state = 'idle'
      g.s.player.hitstun = 0
      const before = g.s.player.form
      const maxBefore = g.s.player.maxHp
      g.playerTransform()
      for (let i = 0; i < 55; i++) { e.hitstun = 999; g.update(1 / 60) }
      entry.transformedTo = g.s.player.form
      entry.formName = g.FORMS ? g.FORMS[g.s.player.form].name : `form ${g.s.player.form}`
      entry.maxHpGain = g.s.player.maxHp - maxBefore
      step(`stage-${stage + 1}-transform`, g.s.player.form === before + 1, `form ${before}->${g.s.player.form}`)
    }

    // Stop any pending enemy action and land the killing blow.
    e.hitstun = 0
    e.invuln = 0
    e.blocking = false
    const hpBefore = e.hp
    g.damageFighter(e, 999999, { source: g.s.player, unblockable: true })
    step(`stage-${stage + 1}-ko`, e.dead && g.s.finish === 'victory', `dead=${e.dead} finish=${g.s.finish}`)
    for (let i = 0; i < 240; i++) g.update(1 / 60)
    step(`stage-${stage + 1}-victory`, g.s.mode === 'victory', `mode=${g.s.mode}`)
    entry.damage = Math.round(g.s.fightDamage)
    entry.enemyHpBefore = Math.round(hpBefore)
    entry.nextLabel = g.dom['btn-next'].textContent
    out.stages.push(entry)

    // Advance via the real button handler.
    g.dom['btn-next'].click()
    if (stage < 7) {
      step(`stage-${stage + 1}-next-intro`, g.s.mode === 'intro' && g.s.enemyIndex === stage + 1, `mode=${g.s.mode} idx=${g.s.enemyIndex}`)
      step(`stage-${stage + 2}-form-carried`, g.s.player.form === stage + 1, `form=${g.s.player.form}`)
    } else {
      step('complete-screen', g.s.mode === 'complete', `mode=${g.s.mode}`)
      step('complete-form-max', g.s.player.form === 8, `form=${g.s.player.form}`)
      step('complete-best', localStorage.getItem('dbs_best') === '8', `best=${localStorage.getItem('dbs_best')}`)
    }
  }

  out.final = {
    mode: g.s.mode,
    form: g.s.player.form,
    runDamage: Math.round(g.s.damageDealt),
    maxCombo: g.s.maxCombo,
    runTime: Math.round(g.s.runTime),
    best: localStorage.getItem('dbs_best'),
    completeText: g.dom['complete-form'].textContent
  }
  g.audio.setEnabled(true)
  return out
}

