  const g = window.__GAME__
  const out = { checks: [], errors: [] }
  const check = (name, ok, detail = '') => {
    out.checks.push({ name, ok, detail })
    if (!ok) out.errors.push(`${name}: ${detail}`)
  }

  g.audio.setEnabled(false)
  g.startGame()
  for (let i = 0; i < 180; i++) g.update(1 / 60)
  check('fight-mode', g.s.mode === 'fight', g.s.mode)

  const p = g.s.player
  const e = g.s.enemy
  p.form = 0
  p.maxHp = 1000
  p.hp = 1000
  p.invuln = 0
  p.hitstun = 0
  p.dead = false
  p.blocking = true
  p.grounded = true
  p.facing = -1
  g.s.finish = null

  // Attacker in front (to the left of a left-facing guard).
  p.hp = 1000
  g.damageFighter(p, 1000, { source: { x: p.x - 120, kind: 'enemy' } })
  const frontLoss = Math.round(1000 - p.hp)
  check('guard-front-blocks', frontLoss > 100 && frontLoss < 220, `loss=${frontLoss}`)

  // Attacker behind (to the right).
  p.hp = 1000
  p.invuln = 0
  p.blocking = true
  p.hitstun = 0
  g.damageFighter(p, 1000, { source: { x: p.x + 120, kind: 'enemy' } })
  const backLoss = Math.round(1000 - p.hp)
  check('guard-back-hits', backLoss > 700, `loss=${backLoss}`)
  out.guard = { frontLoss, backLoss }

  // Spirit Bomb wind-up and invulnerability.
  g.s.player.hp = g.s.player.maxHp
  g.s.player.dead = false
  g.s.player.hitstun = 0
  g.s.player.invuln = 0
  g.s.finish = null
  g.setForm(2)
  for (let i = 0; i < 60; i++) { e.hitstun = 999; g.update(1 / 60) }
  const sp = g.s.player
  sp.spirit = 100
  sp.ki = 100
  sp.cooldowns = [0, 0, 0, 0]
  sp.state = 'idle'
  sp.hitstun = 0
  sp.invuln = 0
  g.s.projectiles.length = 0
  g.playerSkill(3)
  check('spirit-starts', sp.state === 'skill' && sp.skillId === 'spirit', `${sp.state}/${sp.skillId}`)
  const invulnAtStart = sp.invuln
  check('spirit-invuln-window', invulnAtStart >= 1.9, `invuln=${invulnAtStart}`)

  for (let i = 0; i < 30; i++) { e.hitstun = 999; g.update(1 / 60) }
  const hpBefore = sp.hp
  sp.invuln = Math.max(sp.invuln, 0.01)
  const hitLanded = g.damageFighter(sp, 500, { source: { x: e.x, kind: 'enemy' } })
  check('spirit-windup-immune', !hitLanded && sp.hp === hpBefore, `hit=${hitLanded} hp=${sp.hp}/${hpBefore}`)

  let projectileAt = -1
  for (let i = 0; i < 90; i++) {
    e.hitstun = 999
    g.update(1 / 60)
    if (projectileAt < 0 && g.s.projectiles.some((pr) => pr.kind === 'spirit')) projectileAt = i
  }
  check('spirit-projectile-spawned', projectileAt >= 0, `frame=${projectileAt}`)
  check('spirit-skill-completes', sp.skillId === null || sp.state !== 'skill', `state=${sp.state} skill=${sp.skillId}`)
  out.spirit = { invulnAtStart, projectileAt, state: sp.state, spirit: sp.spirit }

  g.audio.setEnabled(true)
  return out
}');
